!
    io = i
!
    CALL PUSHREAL8(cosa)
    cosa = COS(alfa)
    CALL PUSHREAL8(sina)
    sina = SIN(alfa)
!
    DO jo=1,n
      dzdg(jo) = 0.0
      dqdg(jo) = 0.0
    END DO
!
    DO jo=1,n
      dzdm(jo) = 0.0
      dqdm(jo) = 0.0
    END DO
!
!
!
    qtan1 = 0.
    qtan2 = 0.
!
    IF (sharp) THEN
      CALL PUSHCONTROL1B(1)
      scs = 1.0
      sds = 0.0
    ELSE
      scs = ante/dste
      sds = aste/dste
      CALL PUSHCONTROL1B(0)
    END IF
    CALL PUSHINTEGER4(jo)
    ad_count = 1
!
    DO jo=1,n
      CALL PUSHINTEGER4(jp)
      jp = jo + 1
!
      CALL PUSHINTEGER4(jm)
      jm = jo - 1
      CALL PUSHINTEGER4(jq)
      jq = jp + 1
!
      IF (jo .EQ. 1) THEN
        CALL PUSHCONTROL2B(0)
        jm = jo
      ELSE IF (jo .EQ. n - 1) THEN
        CALL PUSHCONTROL2B(1)
        jq = jp
      ELSE IF (jo .EQ. n) THEN
        jp = 1
        IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) THEN
          GOTO 110
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
      ELSE
        CALL PUSHCONTROL2B(3)
      END IF
!
      CALL PUSHREAL8(dso)
      dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then 
      result1 = EPSILON(0.)
      result2 = EPSILON(0.)
      IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) THEN
!
        CALL PUSHREAL8(dsio)
        dsio = 1.0/dso
!
        CALL PUSHREAL8(apan)
        apan = apanel(jo)
!
        CALL PUSHREAL8(rx1)
        rx1 = xi - x(jo)
        CALL PUSHREAL8(ry1)
        ry1 = yi - y(jo)
        CALL PUSHREAL8(rx2)
        rx2 = xi - x(jp)
        CALL PUSHREAL8(ry2)
        ry2 = yi - y(jp)
!
        CALL PUSHREAL8(sx)
        sx = (x(jp)-x(jo))*dsio
        CALL PUSHREAL8(sy)
        sy = (y(jp)-y(jo))*dsio
!
        CALL PUSHREAL8(x1)
        x1 = sx*rx1 + sy*ry1
        CALL PUSHREAL8(x2)
        x2 = sx*rx2 + sy*ry2
        CALL PUSHREAL8(yy)
        yy = sx*ry1 - sy*rx1
!
        rs1 = rx1*rx1 + ry1*ry1
        rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
        IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
          CALL PUSHREAL8(sgn)
          sgn = 1.0
          CALL PUSHCONTROL1B(0)
        ELSE
!------- make sure arctan falls between  -/+  Pi/2
          CALL PUSHREAL8(sgn)
          sgn = SIGN(1.0, yy)
          CALL PUSHCONTROL1B(1)
        END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
        IF (io .NE. jo .AND. rs1 .GT. 0.0) THEN
          CALL PUSHREAL8(g1)
          g1 = LOG(rs1)
          CALL PUSHREAL8(t1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(g1)
          g1 = 0.0
          CALL PUSHREAL8(t1)
          t1 = 0.0
          CALL PUSHCONTROL1B(1)
        END IF
!
        IF (io .NE. jp .AND. rs2 .GT. 0.0) THEN
          CALL PUSHREAL8(g2)
          g2 = LOG(rs2)
          CALL PUSHREAL8(t2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(g2)
          g2 = 0.0
          CALL PUSHREAL8(t2)
          t2 = 0.0
          CALL PUSHCONTROL1B(1)
        END IF
!
        CALL PUSHREAL8(x1i)
        x1i = sx*nxi + sy*nyi
        CALL PUSHREAL8(x2i)
        x2i = sx*nxi + sy*nyi
        CALL PUSHREAL8(yyi)
        yyi = sx*nyi - sy*nxi
!
!
        IF (jo .EQ. n) THEN
          GOTO 120
        ELSE
!
          IF (siglin) THEN
!
!------- set up midpoint quantities
            x0 = 0.5*(x1+x2)
            rs0 = x0*x0 + yy*yy
            CALL PUSHREAL8(g0)
            g0 = LOG(rs0)
            CALL PUSHREAL8(t0)
            t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
            dxinv = 1.0/(x1-x0)
            CALL PUSHREAL8(psum)
            psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
            CALL PUSHREAL8(pdif)
            pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*yy)&
&             *dxinv
!
            psx1 = -(t1-apan)
            psx0 = t0 - apan
            psyy = 0.5*(g1-g0)
!
            pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
            CALL PUSHREAL8(pdx0)
            pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
            pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
            CALL PUSHREAL8(dsm)
            dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
            dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
!
!
!------- dPsi/dm
            dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
            dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-dsim&
&             ))
!
!------- dPsi/dni
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
!
!
            dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
            dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-dsim&
&             ))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
            dxinv = 1.0/(x0-x2)
            CALL PUSHREAL8(psum)
            psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
            CALL PUSHREAL8(pdif)
            pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*yy)&
&             *dxinv
!
            psx0 = -(t0-apan)
            psx2 = t2 - apan
            psyy = 0.5*(g0-g2)
!
            CALL PUSHREAL8(pdx0)
            pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
            pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
            CALL PUSHREAL8(pdyy)
            pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
            CALL PUSHREAL8(dsp)
            dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
            dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
!
!
!------- dPsi/dm
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip-&
&             dsio))
            dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
            dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
            psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
            pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
!
!
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip-&
&             dsio))
            dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
            dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!------ calculate vortex panel contribution to Psi
          dxinv = 1.0/(x1-x2)
          CALL PUSHREAL8(psis)
          psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
          CALL PUSHREAL8(psid)
          psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
          psx1 = 0.5*g1
          psx2 = -(.5*g2)
          psyy = t1 - t2
!
          CALL PUSHREAL8(pdx1)
          pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
          CALL PUSHREAL8(pdx2)
          pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
          CALL PUSHREAL8(pdyy)
          pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
          gsum1 = gamu(jp, 1) + gamu(jo, 1)
          gsum2 = gamu(jp, 2) + gamu(jo, 2)
          gdif1 = gamu(jp, 1) - gamu(jo, 1)
          gdif2 = gamu(jp, 2) - gamu(jo, 2)
!
!
!
!------ dPsi/dGam
          dzdg(jo) = dzdg(jo) + qopi*(psis-psid)
          dzdg(jp) = dzdg(jp) + qopi*(psis+psid)
!
!------ dPsi/dni
          psni = psx1*x1i + psx2*x2i + psyy*yyi
          pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
!
          qtan1 = qtan1 + qopi*(gsum1*psni+gdif1*pdni)
          qtan2 = qtan2 + qopi*(gsum2*psni+gdif2*pdni)
!
          dqdg(jo) = dqdg(jo) + qopi*(psni-pdni)
          dqdg(jp) = dqdg(jp) + qopi*(psni+pdni)
!
          IF (geolin) THEN
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
        END IF
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      CALL PUSHINTEGER4(jo)
      ad_count = ad_count + 1
    END DO
    CALL PUSHCONTROL2B(0)
    CALL PUSHINTEGER4(ad_count)
    GOTO 130
 110 CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL1B(0)
    GOTO 100
 120 CALL PUSHCONTROL2B(2)
    CALL PUSHINTEGER4(ad_count)
!
!
!
 130 psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
    pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
    psigx1 = -(t1-apan)
    psigx2 = t2 - apan
    psigyy = 0.5*(g1-g2)
    pgamx1 = 0.5*g1
    pgamx2 = -(.5*g2)
    pgamyy = t1 - t2
!
    psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
    pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
    sigte1 = 0.5*scs*(gamu(jp, 1)-gamu(jo, 1))
    sigte2 = 0.5*scs*(gamu(jp, 2)-gamu(jo, 2))
    gamte1 = -(.5*sds*(gamu(jp, 1)-gamu(jo, 1)))
    gamte2 = -(.5*sds*(gamu(jp, 2)-gamu(jo, 2)))
!
!
!---- TE panel contribution to Psi
!
!---- dPsi/dGam
    dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
    dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
    dzdg(jo) = dzdg(jo) + hopi*pgam*sds*0.5
    dzdg(jp) = dzdg(jp) - hopi*pgam*sds*0.5
!
!---- dPsi/dni
!
    qtan1 = qtan1 + hopi*(psigni*sigte1+pgamni*gamte1)
    qtan2 = qtan2 + hopi*(psigni*sigte2+pgamni*gamte2)
!
    dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs-pgamni*0.5*sds)
    dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs-pgamni*0.5*sds)
!
    IF (geolin) THEN
      CALL PUSHCONTROL1B(1)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!
!**** Freestream terms
!
!---- dPsi/dn
!
 100 qtan1 = qtan1 + qinf*nyi
    qtan2 = qtan2 - qinf*nxi
!
!---- dPsi/dQinf
!
!---- dPsi/dalfa
!
    IF (.NOT.limage) THEN
      CALL PUSHREAL8(scs)
      CALL PUSHINTEGER4(jq)
      CALL PUSHINTEGER4(jp)
      CALL PUSHINTEGER4(jo)
      CALL PUSHINTEGER4(jm)
      CALL PUSHREAL8(pgam)
      CALL PUSHREAL8(sy)
      CALL PUSHREAL8(sx)
      CALL PUSHREAL8(dsio)
      CALL PUSHREAL8(dsp)
      CALL PUSHREAL8(psis)
      CALL PUSHREAL8(apan)
      CALL PUSHREAL8(dso)
      CALL PUSHREAL8(x2i)
      CALL PUSHREAL8(dsm)
      CALL PUSHREAL8(yy)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(rs2)
      CALL PUSHREAL8(x1)
      CALL PUSHREAL8(rs1)
      CALL PUSHREAL8(psig)
      CALL PUSHREAL8(psid)
      CALL PUSHREAL8(pdx0)
      CALL PUSHREAL8(ry2)
      CALL PUSHREAL8(ry1)
      CALL PUSHREAL8(pdif)
      CALL PUSHREAL8(t2)
      CALL PUSHREAL8(t1)
      CALL PUSHREAL8(t0)
      CALL PUSHREAL8(x1i)
      CALL PUSHREAL8(g2)
      CALL PUSHREAL8(psum)
      CALL PUSHREAL8(g1)
      CALL PUSHREAL8(g0)
      CALL PUSHREAL8(yyi)
      CALL PUSHREAL8(sds)
      CALL PUSHREAL8(rx2)
      CALL PUSHREAL8(rx1)
      CALL PUSHREAL8(sgn)
      CALL PUSHCONTROL2B(0)
    ELSE
      CALL PUSHINTEGER4(jo)
      ad_count0 = 1
!
!
!
      DO jo=1,n
        CALL PUSHINTEGER4(jp)
        jp = jo + 1
!
        CALL PUSHINTEGER4(jm)
        jm = jo - 1
        CALL PUSHINTEGER4(jq)
        jq = jp + 1
!
        IF (jo .EQ. 1) THEN
          CALL PUSHCONTROL2B(0)
          jm = jo
        ELSE IF (jo .EQ. n - 1) THEN
          CALL PUSHCONTROL2B(1)
          jq = jp
        ELSE IF (jo .EQ. n) THEN
          jp = 1
          IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) THEN
            GOTO 140
          ELSE
            CALL PUSHCONTROL2B(2)
          END IF
        ELSE
          CALL PUSHCONTROL2B(3)
        END IF
!
        CALL PUSHREAL8(dso)
        dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then
        result1 = EPSILON(0.)
        result2 = EPSILON(0.)
        IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) &
&       THEN
!
          CALL PUSHREAL8(dsio)
          dsio = 1.0/dso
!
!cc     APAN = APANEL(JO)
          CALL PUSHREAL8(apan)
          apan = pi - apanel(jo) + 2.0*alfa
!
          CALL PUSHREAL8(xjo)
          xjo = x(jo) + 2.0*(yimage+y(jo))*sina
          CALL PUSHREAL8(yjo)
          yjo = y(jo) - 2.0*(yimage+y(jo))*cosa
          CALL PUSHREAL8(xjp)
          xjp = x(jp) + 2.0*(yimage+y(jp))*sina
          CALL PUSHREAL8(yjp)
          yjp = y(jp) - 2.0*(yimage+y(jp))*cosa
!
          CALL PUSHREAL8(rx1)
          rx1 = xi - xjo
          CALL PUSHREAL8(ry1)
          ry1 = yi - yjo
          CALL PUSHREAL8(rx2)
          rx2 = xi - xjp
          CALL PUSHREAL8(ry2)
          ry2 = yi - yjp
!
          CALL PUSHREAL8(sx)
          sx = (xjp-xjo)*dsio
          CALL PUSHREAL8(sy)
          sy = (yjp-yjo)*dsio
!
          CALL PUSHREAL8(x1)
          x1 = sx*rx1 + sy*ry1
          CALL PUSHREAL8(x2)
          x2 = sx*rx2 + sy*ry2
          CALL PUSHREAL8(yy)
          yy = sx*ry1 - sy*rx1
!
          CALL PUSHREAL8(rs1)
          rs1 = rx1*rx1 + ry1*ry1
          CALL PUSHREAL8(rs2)
          rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
          IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
            CALL PUSHREAL8(sgn)
            sgn = 1.0
            CALL PUSHCONTROL1B(0)
          ELSE
!------- make sure arctan falls between  -/+  Pi/2
            CALL PUSHREAL8(sgn)
            sgn = SIGN(1.0, yy)
            CALL PUSHCONTROL1B(1)
          END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
          CALL PUSHREAL8(g1)
          g1 = LOG(rs1)
          CALL PUSHREAL8(t1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
!
          CALL PUSHREAL8(g2)
          g2 = LOG(rs2)
          CALL PUSHREAL8(t2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
!
          CALL PUSHREAL8(x1i)
          x1i = sx*nxi + sy*nyi
          CALL PUSHREAL8(x2i)
          x2i = sx*nxi + sy*nyi
          CALL PUSHREAL8(yyi)
          yyi = sx*nyi - sy*nxi
!
!
          IF (jo .EQ. n) THEN
            GOTO 150
          ELSE
!
            IF (siglin) THEN
!
!------- set up midpoint quantities
              x0 = 0.5*(x1+x2)
              rs0 = x0*x0 + yy*yy
              CALL PUSHREAL8(g0)
              g0 = LOG(rs0)
              CALL PUSHREAL8(t0)
              t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
              dxinv = 1.0/(x1-x0)
              CALL PUSHREAL8(psum)
              psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
              CALL PUSHREAL8(pdif)
              pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*&
&               yy)*dxinv
!
              psx1 = -(t1-apan)
              psx0 = t0 - apan
              psyy = 0.5*(g1-g0)
!
              pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
              CALL PUSHREAL8(pdx0)
              pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
              pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
              CALL PUSHREAL8(dsm)
              dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
              dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
!
!
!------- dPsi/dm
              dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
              dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-&
&               dsim))
!
!------- dPsi/dni
              psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
              pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
!
!
              dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
              dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-&
&               dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
              dxinv = 1.0/(x0-x2)
              CALL PUSHREAL8(psum)
              psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
              CALL PUSHREAL8(pdif)
              pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*&
&               yy)*dxinv
!
              psx0 = -(t0-apan)
              psx2 = t2 - apan
              psyy = 0.5*(g0-g2)
!
              CALL PUSHREAL8(pdx0)
              pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
              pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
              CALL PUSHREAL8(pdyy)
              pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
              CALL PUSHREAL8(dsp)
              dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
              dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
!
!
!------- dPsi/dm
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip&
&               -dsio))
              dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
              dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
!
!
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip&
&               -dsio))
              dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
              dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
!------ calculate vortex panel contribution to Psi
            dxinv = 1.0/(x1-x2)
            CALL PUSHREAL8(psis)
            psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
            CALL PUSHREAL8(psid)
            psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
            psx1 = 0.5*g1
            psx2 = -(.5*g2)
            psyy = t1 - t2
!
            CALL PUSHREAL8(pdx1)
            pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
            CALL PUSHREAL8(pdx2)
            pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
            CALL PUSHREAL8(pdyy)
            pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
            gsum1 = gamu(jp, 1) + gamu(jo, 1)
            gsum2 = gamu(jp, 2) + gamu(jo, 2)
            gdif1 = gamu(jp, 1) - gamu(jo, 1)
            gdif2 = gamu(jp, 2) - gamu(jo, 2)
!
!
!
!------ dPsi/dGam
            dzdg(jo) = dzdg(jo) - qopi*(psis-psid)
            dzdg(jp) = dzdg(jp) - qopi*(psis+psid)
!
!------ dPsi/dni
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
!
            qtan1 = qtan1 - qopi*(gsum1*psni+gdif1*pdni)
            qtan2 = qtan2 - qopi*(gsum2*psni+gdif2*pdni)
!
            dqdg(jo) = dqdg(jo) - qopi*(psni-pdni)
            dqdg(jp) = dqdg(jp) - qopi*(psni+pdni)
!
            CALL PUSHCONTROL1B(1)
          END IF
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        CALL PUSHINTEGER4(jo)
        ad_count0 = ad_count0 + 1
      END DO
      CALL PUSHCONTROL2B(0)
      CALL PUSHINTEGER4(ad_count0)
      GOTO 160
 140  CALL PUSHCONTROL2B(1)
      CALL PUSHINTEGER4(ad_count0)
      CALL PUSHREAL8(scs)
      CALL PUSHREAL8(pgam)
      CALL PUSHREAL8(sy)
      CALL PUSHREAL8(sx)
      CALL PUSHREAL8(dsio)
      CALL PUSHREAL8(yjp)
      CALL PUSHREAL8(yjo)
      CALL PUSHREAL8(dsp)
      CALL PUSHREAL8(psis)
      CALL PUSHREAL8(apan)
      CALL PUSHREAL8(dso)
      CALL PUSHREAL8(x2i)
      CALL PUSHREAL8(dsm)
      CALL PUSHREAL8(yy)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(rs2)
      CALL PUSHREAL8(x1)
      CALL PUSHREAL8(rs1)
      CALL PUSHREAL8(psig)
      CALL PUSHREAL8(psid)
      CALL PUSHREAL8(pdx0)
      CALL PUSHREAL8(ry2)
      CALL PUSHREAL8(ry1)
      CALL PUSHREAL8(pdif)
      CALL PUSHREAL8(t2)
      CALL PUSHREAL8(t1)
      CALL PUSHREAL8(t0)
      CALL PUSHREAL8(x1i)
      CALL PUSHREAL8(g2)
      CALL PUSHREAL8(psum)
      CALL PUSHREAL8(g1)
      CALL PUSHREAL8(g0)
      CALL PUSHREAL8(yyi)
      CALL PUSHREAL8(sds)
      CALL PUSHREAL8(rx2)
      CALL PUSHREAL8(rx1)
      CALL PUSHREAL8(sgn)
      CALL PUSHREAL8(xjp)
      CALL PUSHREAL8(xjo)
      CALL PUSHCONTROL2B(1)
      GOTO 170
 150  CALL PUSHCONTROL2B(2)
      CALL PUSHINTEGER4(ad_count0)
!
!
!
 160  CALL PUSHREAL8(psig)
      psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
      CALL PUSHREAL8(pgam)
      pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
      psigx1 = -(t1-apan)
      psigx2 = t2 - apan
      psigyy = 0.5*(g1-g2)
      pgamx1 = 0.5*g1
      pgamx2 = -(.5*g2)
      pgamyy = t1 - t2
!
      psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
      sigte1 = 0.5*scs*(gamu(jp, 1)-gamu(jo, 1))
      sigte2 = 0.5*scs*(gamu(jp, 2)-gamu(jo, 2))
      gamte1 = -(.5*sds*(gamu(jp, 1)-gamu(jo, 1)))
      gamte2 = -(.5*sds*(gamu(jp, 2)-gamu(jo, 2)))
!
!
!---- TE panel contribution to Psi
!
!---- dPsi/dGam
      dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
      dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
      dzdg(jo) = dzdg(jo) - hopi*pgam*sds*0.5
      dzdg(jp) = dzdg(jp) + hopi*pgam*sds*0.5
!
!---- dPsi/dni
!
      qtan1 = qtan1 + hopi*(psigni*sigte1-pgamni*gamte1)
      qtan2 = qtan2 + hopi*(psigni*sigte2-pgamni*gamte2)
!
      dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs+pgamni*0.5*sds)
      dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs+pgamni*0.5*sds)
!
      CALL PUSHREAL8(scs)
      CALL PUSHINTEGER4(jq)
      CALL PUSHINTEGER4(jp)
      CALL PUSHINTEGER4(jo)
      CALL PUSHINTEGER4(jm)
      CALL PUSHREAL8(pgam)
      CALL PUSHREAL8(sy)
      CALL PUSHREAL8(sx)
      CALL PUSHREAL8(dsio)
      CALL PUSHREAL8(yjp)
      CALL PUSHREAL8(yjo)
      CALL PUSHREAL8(dsp)
      CALL PUSHREAL8(psis)
      CALL PUSHREAL8(apan)
      CALL PUSHREAL8(dso)
      CALL PUSHREAL8(x2i)
      CALL PUSHREAL8(dsm)
      CALL PUSHREAL8(yy)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(rs2)
      CALL PUSHREAL8(x1)
      CALL PUSHREAL8(rs1)
      CALL PUSHREAL8(psig)
      CALL PUSHREAL8(psid)
      CALL PUSHREAL8(pdx0)
      CALL PUSHREAL8(ry2)
      CALL PUSHREAL8(ry1)
      CALL PUSHREAL8(pdif)
      CALL PUSHREAL8(t2)
      CALL PUSHREAL8(t1)
      CALL PUSHREAL8(t0)
      CALL PUSHREAL8(x1i)
      CALL PUSHREAL8(g2)
      CALL PUSHREAL8(psum)
      CALL PUSHREAL8(g1)
      CALL PUSHREAL8(g0)
      CALL PUSHREAL8(yyi)
      CALL PUSHREAL8(sds)
      CALL PUSHREAL8(rx2)
      CALL PUSHREAL8(rx1)
      CALL PUSHREAL8(sgn)
      CALL PUSHREAL8(xjp)
      CALL PUSHREAL8(xjo)
      CALL PUSHCONTROL2B(2)
    END IF
 170 CONTINUE
  END SUBROUTINE PSILIN_FWD

