      sigte2 = 0.5*scs*(gamu(jp, 2)-gamu(jo, 2))
      gamte2 = -(.5*sds*(gamu(jp, 2)-gamu(jo, 2)))
      tempb1 = hopi*qtan2b
      psignib = psignib + sigte2*tempb1
      sigte2b = psigni*tempb1
      pgamnib = pgamnib + gamte2*tempb1
      gamte2b = pgamni*tempb1
      sigte1 = 0.5*scs*(gamu(jp, 1)-gamu(jo, 1))
      gamte1 = -(.5*sds*(gamu(jp, 1)-gamu(jo, 1)))
      tempb1 = hopi*qtan1b
      psignib = psignib + sigte1*tempb1
      sigte1b = psigni*tempb1
      pgamnib = pgamnib + gamte1*tempb1
      gamte1b = pgamni*tempb1
      tempb1 = -(hopi*0.5*dzdgb(jp))
      pgamb = sds*tempb1
      sdsb = sdsb + pgam*tempb1
      tempb1 = hopi*0.5*dzdgb(jo)
      pgamb = pgamb + sds*tempb1
      sdsb = sdsb + pgam*tempb1 - (gamu(jp, 2)-gamu(jo, 2))*.5*gamte2b -&
&       (gamu(jp, 1)-gamu(jo, 1))*.5*gamte1b
      tempb1 = hopi*0.5*dzdgb(jp)
      psigb = scs*tempb1
      scsb = scsb + psig*tempb1
      tempb1 = -(hopi*0.5*dzdgb(jo))
      psigb = psigb + scs*tempb1
      scsb = scsb + psig*tempb1 + (gamu(jp, 2)-gamu(jo, 2))*0.5*sigte2b &
&       + (gamu(jp, 1)-gamu(jo, 1))*0.5*sigte1b
      tempb1 = -(sds*.5*gamte2b)
      gamub(jp, 2) = gamub(jp, 2) + tempb1
      gamub(jo, 2) = gamub(jo, 2) - tempb1
      tempb1 = -(sds*.5*gamte1b)
      gamub(jp, 1) = gamub(jp, 1) + tempb1
      gamub(jo, 1) = gamub(jo, 1) - tempb1
      tempb1 = scs*0.5*sigte2b
      gamub(jp, 2) = gamub(jp, 2) + tempb1
      gamub(jo, 2) = gamub(jo, 2) - tempb1
      tempb1 = scs*0.5*sigte1b
      gamub(jp, 1) = gamub(jp, 1) + tempb1
      gamub(jo, 1) = gamub(jo, 1) - tempb1
      pgamx1b = x1i*pgamnib
      x1ib = x1ib + pgamx1*pgamnib + psigx1*psignib
      pgamx2b = x2i*pgamnib
      x2ib = x2ib + pgamx2*pgamnib + psigx2*psignib
      pgamyyb = yyi*pgamnib
      yyib = yyib + pgamyy*pgamnib + psigyy*psignib
      psigx1b = x1i*psignib
      psigx2b = x2i*psignib
      psigyyb = yyi*psignib
      t1b = t1b + pgamyyb + yy*pgamb - psigx1b - x1*psigb
      t2b = t2b + psigx2b - pgamyyb + x2*psigb - yy*pgamb
      apanb = apanb + psigx1b - psigx2b + (x1-x2)*psigb
      x1b = x1b + (g1*0.5-1.0)*pgamb - (t1-apan)*psigb
      x2b = x2b + (1.0-g2*0.5)*pgamb + (t2-apan)*psigb
      yyb = yyb + (t1-t2)*pgamb + (g1-g2)*0.5*psigb
      tempb1 = yy*0.5*psigb
      g2b = g2b - .5*pgamx2b - 0.5*psigyyb - x2*0.5*pgamb - tempb1
      g1b = g1b + 0.5*pgamx1b + 0.5*psigyyb + x1*0.5*pgamb + tempb1
    END IF
    CALL POPINTEGER4(ad_count)
    DO i0=1,ad_count
      IF (i0 .EQ. 1) THEN
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          GOTO 150
        ELSE IF (branch .EQ. 1) THEN
