        ELSE
          rs2 = rx2*rx2 + ry2*ry2
          rs1 = rx1*rx1 + ry1*ry1
          tempb1 = qopi*qtan2b
          gsum2 = gamu(jp, 2) + gamu(jo, 2)
          gdif2 = gamu(jp, 2) - gamu(jo, 2)
          dxinv = 1.0/(x1-x2)
          psx1 = 0.5*g1
          pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
          psx2 = -(.5*g2)
          pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
          psyy = t1 - t2
          pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
          pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
          psni = psx1*x1i + psx2*x2i + psyy*yyi
          psnib = qopi*dqdgb(jp) + qopi*dqdgb(jo) + gsum2*tempb1
          pdnib = qopi*dqdgb(jp) + gdif2*tempb1 - qopi*dqdgb(jo)
          gsum2b = psni*tempb1
          gdif2b = pdni*tempb1
          gdif1 = gamu(jp, 1) - gamu(jo, 1)
          gsum1 = gamu(jp, 1) + gamu(jo, 1)
          tempb1 = qopi*qtan1b
          gsum1b = psni*tempb1
          psnib = psnib + gsum1*tempb1
          gdif1b = pdni*tempb1
          pdnib = pdnib + gdif1*tempb1
          pdx1b = x1i*pdnib
          x1ib = x1ib + pdx1*pdnib + psx1*psnib
          pdx2b = x2i*pdnib
          x2ib = x2ib + pdx2*pdnib + psx2*psnib
          pdyyb = yyi*pdnib
          yyib = yyib + pdyy*pdnib + psyy*psnib
          gamub(jp, 2) = gamub(jp, 2) + gdif2b
          gamub(jo, 2) = gamub(jo, 2) - gdif2b
          gamub(jp, 1) = gamub(jp, 1) + gdif1b
          gamub(jo, 1) = gamub(jo, 1) - gdif1b
          gamub(jp, 2) = gamub(jp, 2) + gsum2b
          gamub(jo, 2) = gamub(jo, 2) + gsum2b
          gamub(jp, 1) = gamub(jp, 1) + gsum1b
          gamub(jo, 1) = gamub(jo, 1) + gsum1b
          CALL POPREAL8(pdyy)
          tempb1 = dxinv*pdyyb
          psyyb = yyi*psnib + (x1+x2)*tempb1
          x1b = x1b + psyy*tempb1
          x2b = x2b + psyy*tempb1
          yyb = yyb - (g1-g2)*tempb1
          g1b = g1b - yy*tempb1
          g2b = g2b + yy*tempb1
          CALL POPREAL8(pdx2)
          tempb1 = dxinv*pdx2b
          psx2b = x2i*psnib + (x1+x2)*tempb1
          psisb = qopi*dzdgb(jp) + qopi*dzdgb(jo) + tempb1
          psidb = qopi*dzdgb(jp) + tempb1 - qopi*dzdgb(jo)
          x1b = x1b + psx2*tempb1
          x2b = x2b + (psx2+g2)*tempb1
          g2b = g2b + x2*tempb1
          CALL POPREAL8(pdx1)
          tempb1 = dxinv*pdx1b
          psx1b = x1i*psnib + (x1+x2)*tempb1
          x1b = x1b + (psx1-g1)*tempb1
          x2b = x2b + psx1*tempb1
          psisb = psisb + tempb1
          g1b = g1b - x1*tempb1
          psidb = psidb - tempb1
          dxinvb = ((x1+x2)*psyy-yy*(g1-g2))*pdyyb + ((x1+x2)*psx2+psis+&
&           x2*g2+psid)*pdx2b + ((x1+x2)*psx1+psis-x1*g1-psid)*pdx1b + (&
&           (x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1**2-x2**2))*psidb
          CALL POPREAL8(psid)
          tempb1 = dxinv*psidb
