          x2b = x2b + psis*tempb1
          psisb = psisb + (x1+x2)*tempb1
          t1b = t1b + psyyb + yy*psisb
          t2b = t2b - psyyb - yy*psisb
          tempb0 = 0.5*tempb1
          g2b = g2b + rs2*tempb0 - .5*psx2b - x2*0.5*psisb
          g1b = g1b + 0.5*psx1b + x1*0.5*psisb - rs1*tempb0
          rs2b = g2*tempb0
          rs1b = -(g1*tempb0)
          CALL POPREAL8(psis)
          yyb = yyb + (t1-t2)*psisb
          tempb1 = -(dxinvb/(x1-x2)**2)
          x1b = x1b + 2*x1*tempb0 + (g1*0.5-1.0)*psisb + tempb1
          x2b = x2b + (1.0-g2*0.5)*psisb - 2*x2*tempb0 - tempb1
          CALL POPCONTROL1B(branch)
