            psx2 = t2 - apan
            psyy = 0.5*(g0-g2)
            psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
            dsip = 1.0/dsp
            tempb1 = qopi*dqdmb(jq)
            psnib = dsip*tempb1
            dsipb = (psni+pdni)*tempb1
            pdnib = dsip*tempb1
            tempb1 = qopi*dqdmb(jp)
            psnib = psnib + dsio*tempb1
            dsiob = (psni-pdni)*tempb1
            pdnib = pdnib - dsio*tempb1
            tempb1 = qopi*dqdmb(jo)
            psnib = psnib - (dsip+dsio)*tempb1
            dsipb = dsipb - (psni+pdni)*tempb1
            dsiob = dsiob + (pdni-psni)*tempb1
            pdnib = pdnib - (dsip-dsio)*tempb1
            pdx0b = (x1i+x2i)*0.5*pdnib
            tempb1 = pdx0*0.5*pdnib
            pdx2b = x2i*pdnib
            x2ib = x2ib + pdx2*pdnib + tempb1
            pdyyb = yyi*pdnib
            yyib = yyib + pdyy*pdnib + psyy*psnib
            x1ib = x1ib + tempb1
            tempb1 = psx0*0.5*psnib
            x2ib = x2ib + psx2*psnib + tempb1
            x1ib = x1ib + tempb1
            tempb1 = qopi*dzdmb(jq)
            psumb = dsip*tempb1
            dsipb = dsipb + (psum+pdif)*tempb1
            pdifb = dsip*tempb1
            tempb1 = qopi*dzdmb(jp)
            psumb = psumb + dsio*tempb1
            dsiob = dsiob + (psum-pdif)*tempb1
            pdifb = pdifb - dsio*tempb1
            tempb1 = qopi*dzdmb(jo)
            psumb = psumb - (dsip+dsio)*tempb1
            dsipb = dsipb - (psum+pdif)*tempb1
            dsiob = dsiob + (pdif-psum)*tempb1
            pdifb = pdifb - (dsip-dsio)*tempb1
            dspb = -(dsipb/dsp**2)
            CALL POPREAL8(dsp)
            IF ((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2 .EQ. 0.0_8) THEN
              tempb1 = 0.0_8
            ELSE
              tempb1 = dspb/(2.0*SQRT((x(jq)-x(jo))**2+(y(jq)-y(jo))**2)&
&               )
            END IF
            tempb0 = 2*(x(jq)-x(jo))*tempb1
            tempb = 2*(y(jq)-y(jo))*tempb1
            yb0(jq) = yb0(jq) + tempb
            yb0(jo) = yb0(jo) - tempb
            xb0(jq) = xb0(jq) + tempb0
            xb0(jo) = xb0(jo) - tempb0
            x0 = 0.5*(x1+x2)
            dxinv = 1.0/(x0-x2)
            CALL POPREAL8(pdyy)
            tempb1 = dxinv*pdyyb
            psyyb = yyi*psnib + (x0+x2)*tempb1
            x0b = psyy*tempb1
            x2b = x2b + psyy*tempb1
            tempb0 = 2.0*tempb1
            yyb = yyb + (t0-t2)*tempb0
            t0b = yy*tempb0
            t2b = t2b - yy*tempb0
            tempb1 = dxinv*pdx2b
            psx2b = x2i*psnib + (x0+x2)*tempb1
            x2b = x2b + tempb0 + (psx2-(t2-apan)*2.0)*tempb1
            x0b = x0b + psx2*tempb1 - tempb0
            psumb = psumb + tempb1
