            x2b = x2b + psx0*tempb1
            psumb = psumb + tempb1
            tempb0 = x0*2.0*tempb1
            pdifb = pdifb - tempb1
            rs0 = x0*x0 + yy*yy
            dxinvb = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*pdyyb + ((x0+&
&             x2)*psx2+psum+pdif-2.0*(x2*(t2-apan)))*pdx2b + ((x0+x2)*&
&             psx0+psum+2.0*(x0*(t0-apan))-pdif)*pdx0b + ((x0+x2)*psum+&
&             rs0*(t0-apan)+(x2-x0)*yy-rs2*(t2-apan))*pdifb
            CALL POPREAL8(pdif)
