            t0b = t0b + tempb0 + rs0*tempb1 - psx0b - x0*psumb
            apanb = apanb + psx0b - tempb0 - psx2b + (rs2-rs0)*tempb1 + &
&             (x0-x2)*psumb
            t2b = t2b + psx2b + x2*psumb - rs2*tempb1
            rs0b = (t0-apan)*tempb1
            yyb = yyb + (x2-x0)*tempb1 + (g0-g2)*0.5*psumb
            rs2b = rs2b - (t2-apan)*tempb1
            CALL POPREAL8(psum)
            tempb1 = yy*0.5*psumb
            g0b = 0.5*psyyb + tempb1
            g2b = g2b - 0.5*psyyb - tempb1
            tempb1 = -(dxinvb/(x0-x2)**2)
            x2b = x2b + (t2-apan)*psumb - tempb1
            x0b = x0b + tempb1 - (t0-apan)*psumb
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
            psx0 = t0 - apan
            psx1 = -(t1-apan)
            psyy = 0.5*(g1-g0)
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            dsim = 1.0/dsm
            tempb1 = qopi*dqdmb(jp)
            psnib = (dsio+dsim)*tempb1
            dsiob = dsiob + (psni+pdni)*tempb1
            dsimb = (psni-pdni)*tempb1
            pdnib = (dsio-dsim)*tempb1
            tempb1 = qopi*dqdmb(jo)
            psnib = psnib - dsio*tempb1
            dsiob = dsiob - (psni+pdni)*tempb1
            pdnib = pdnib - dsio*tempb1
            tempb1 = qopi*dqdmb(jm)
            pdnib = pdnib + dsim*tempb1
            dsimb = dsimb + (pdni-psni)*tempb1
            psnib = psnib - dsim*tempb1
            pdx1b = x1i*pdnib
            pdx0b = (x1i+x2i)*0.5*pdnib
            tempb1 = pdx0*0.5*pdnib
            x1ib = x1ib + pdx1*pdnib + tempb1
            pdyyb = yyi*pdnib
            yyib = yyib + pdyy*pdnib + psyy*psnib
            x2ib = x2ib + tempb1
            tempb1 = psx0*0.5*psnib
            x1ib = x1ib + psx1*psnib + tempb1
            x2ib = x2ib + tempb1
            tempb1 = qopi*dzdmb(jp)
            psumb = (dsio+dsim)*tempb1
            dsiob = dsiob + (psum+pdif)*tempb1
            dsimb = dsimb + (psum-pdif)*tempb1
            pdifb = (dsio-dsim)*tempb1
            tempb1 = qopi*dzdmb(jo)
            psumb = psumb - dsio*tempb1
            dsiob = dsiob - (psum+pdif)*tempb1
            pdifb = pdifb - dsio*tempb1
            tempb1 = qopi*dzdmb(jm)
            pdifb = pdifb + dsim*tempb1
            dsimb = dsimb + (pdif-psum)*tempb1
            psumb = psumb - dsim*tempb1
            dsmb = -(dsimb/dsm**2)
            CALL POPREAL8(dsm)
            IF ((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2 .EQ. 0.0_8) THEN
