            ELSE
              tempb1 = dsmb/(2.0*SQRT((x(jp)-x(jm))**2+(y(jp)-y(jm))**2)&
&               )
            END IF
            tempb0 = 2*(x(jp)-x(jm))*tempb1
            tempb = 2*(y(jp)-y(jm))*tempb1
            yb0(jp) = yb0(jp) + tempb
            yb0(jm) = yb0(jm) - tempb
            xb0(jp) = xb0(jp) + tempb0
            xb0(jm) = xb0(jm) - tempb0
            dxinv = 1.0/(x1-x0)
            tempb1 = dxinv*pdyyb
            psyyb = yyi*psnib + (x1+x0)*tempb1
            x1b = x1b + psyy*tempb1
            x0b = x0b + psyy*tempb1
            tempb0 = 2.0*tempb1
            yyb = yyb + (t1-t0)*tempb0
            t1b = t1b + yy*tempb0
            t0b = t0b - yy*tempb0
            CALL POPREAL8(pdx0)
            tempb1 = dxinv*pdx0b
            psx0b = (x1i+x2i)*0.5*psnib + (x1+x0)*tempb1
            x0b = x0b + tempb0 + (psx0-(t0-apan)*2.0)*tempb1
            x1b = x1b + psx0*tempb1 - tempb0
            psumb = psumb + tempb1
            pdifb = pdifb + tempb1
            tempb0 = -(x0*2.0*tempb1)
            t0b = t0b + tempb0
            apanb = apanb - tempb0
            tempb1 = dxinv*pdx1b
            psx1b = x1i*psnib + (x1+x0)*tempb1
            x1b = x1b + (psx1+(t1-apan)*2.0)*tempb1
            x0b = x0b + psx1*tempb1
            psumb = psumb + tempb1
            tempb0 = x1*2.0*tempb1
            pdifb = pdifb - tempb1
            dxinvb = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*pdyyb + ((x1+&
&             x0)*psx0+psum+pdif-2.0*(x0*(t0-apan)))*pdx0b + ((x1+x0)*&
&             psx1+psum+2.0*(x1*(t1-apan))-pdif)*pdx1b + ((x1+x0)*psum+&
&             rs1*(t1-apan)+(x0-x1)*yy-rs0*(t0-apan))*pdifb
            CALL POPREAL8(pdif)
            tempb1 = dxinv*pdifb
            x1b = x1b + (psum-yy)*tempb1
            x0b = x0b + (psum+yy)*tempb1
            psumb = psumb + (x1+x0)*tempb1
            t1b = t1b + tempb0 + rs1*tempb1 - psx1b - x1*psumb
            apanb = apanb + psx1b - tempb0 - psx0b + (rs0-rs1)*tempb1 + &
&             (x1-x0)*psumb
            t0b = t0b + psx0b + x0*psumb - rs0*tempb1
            rs1b = rs1b + (t1-apan)*tempb1
            yyb = yyb + (x0-x1)*tempb1
            rs0b = rs0b - (t0-apan)*tempb1
            CALL POPREAL8(psum)
            tempb1 = yy*0.5*psumb
            g1b = g1b + 0.5*psyyb + tempb1
            g0b = g0b - 0.5*psyyb - tempb1
            tempb1 = -(dxinvb/(x1-x0)**2)
            rs0b = rs0b + g0b/rs0
            x0b = x0b + (t0-apan)*psumb + sgn**2*yy*t0b/((sgn*x0)**2+(&
&             sgn*yy)**2) - tempb1 + 2*x0*rs0b
            x1b = x1b + tempb1 - (t1-apan)*psumb + 0.5*x0b
            yyb = yyb + (g1-g0)*0.5*psumb + 2*yy*rs0b - sgn**2*x0*t0b/((&
&             sgn*x0)**2+(sgn*yy)**2)
            CALL POPREAL8(t0)
            CALL POPREAL8(g0)
            x2b = x2b + 0.5*x0b
          ELSE
            dsiob = 0.0_8
          END IF
        END IF
      END IF
      CALL POPREAL8(yyi)
      sxb = nyi*yyib + nxi*x2ib + nxi*x1ib
      nyib = nyib + sx*yyib + sy*x2ib + sy*x1ib
      syb = nyi*x2ib - nxi*yyib + nyi*x1ib
      nxib = nxib + sx*x2ib - sy*yyib + sx*x1ib
      CALL POPREAL8(x2i)
      CALL POPREAL8(x1i)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(t2)
        x2b = x2b + sgn**2*yy*t2b/((sgn*x2)**2+(sgn*yy)**2)
        yyb = yyb - sgn**2*x2*t2b/((sgn*x2)**2+(sgn*yy)**2)
        CALL POPREAL8(g2)
        rs2b = rs2b + g2b/rs2
      ELSE
        CALL POPREAL8(t2)
        CALL POPREAL8(g2)
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(t1)
        x1b = x1b + sgn**2*yy*t1b/((sgn*x1)**2+(sgn*yy)**2)
        yyb = yyb - sgn**2*x1*t1b/((sgn*x1)**2+(sgn*yy)**2)
        CALL POPREAL8(g1)
        rs1b = rs1b + g1b/rs1
