        jp = jo + 1
!
        jm = jo - 1
        jq = jp + 1
!
        IF (jo .EQ. 1) THEN
          jm = jo
        ELSE IF (jo .EQ. n - 1) THEN
          jq = jp
        ELSE IF (jo .EQ. n) THEN
          jp = 1
          IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO &
&            99999
        END IF
!
        dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then
        result1 = EPSILON(0.)
        result2 = EPSILON(0.)
        IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) &
&       THEN
!
          dsio = 1.0/dso
!
!cc     APAN = APANEL(JO)
          apan = pi - apanel(jo) + 2.0*alfa
!
          xjo = x(jo) + 2.0*(yimage+y(jo))*sina
          yjo = y(jo) - 2.0*(yimage+y(jo))*cosa
          xjp = x(jp) + 2.0*(yimage+y(jp))*sina
          yjp = y(jp) - 2.0*(yimage+y(jp))*cosa
!
          rx1 = xi - xjo
          ry1 = yi - yjo
          rx2 = xi - xjp
          ry2 = yi - yjp
!
          sx = (xjp-xjo)*dsio
          sy = (yjp-yjo)*dsio
!
          x1 = sx*rx1 + sy*ry1
          x2 = sx*rx2 + sy*ry2
          yy = sx*ry1 - sy*rx1
!
          rs1 = rx1*rx1 + ry1*ry1
          rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
          IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
            sgn = 1.0
          ELSE
!------- make sure arctan falls between  -/+  Pi/2
            sgn = SIGN(1.0, yy)
          END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
          g1 = LOG(rs1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
!
          g2 = LOG(rs2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
!
          x1i = sx*nxi + sy*nyi
          x2i = sx*nxi + sy*nyi
          yyi = sx*nyi - sy*nxi
!
          IF (geolin) THEN
            nxo = nx(jo)
            nyo = ny(jo)
            nxp = nx(jp)
            nyp = ny(jp)
!
            x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy&
&             *nyo)
            x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
            x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
            x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*&
&             nyp)
            yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*&
&             nxo)
            yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
          END IF
!
          IF (jo .EQ. n) THEN
            GOTO 120
          ELSE
!
            IF (siglin) THEN
!
!------- set up midpoint quantities
              x0 = 0.5*(x1+x2)
              rs0 = x0*x0 + yy*yy
              g0 = LOG(rs0)
              t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
              dxinv = 1.0/(x1-x0)
              psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
              pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*&
&               yy)*dxinv
!
              psx1 = -(t1-apan)
              psx0 = t0 - apan
              psyy = 0.5*(g1-g0)
!
              pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
              pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
              pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
              dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
              dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
              ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
              sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
              dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-&
&               dsim))
!
!------- dPsi/dni
              psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
              pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
              dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-&
&               dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
              dxinv = 1.0/(x0-x2)
              psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
              pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*&
&               yy)*dxinv
!
              psx0 = -(t0-apan)
              psx2 = t2 - apan
              psyy = 0.5*(g0-g2)
!
              pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
              pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
              pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
              dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
              dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
              ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
              sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip&
&               -dsio))
              dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
              dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip&
&               -dsio))
              dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
              dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
            END IF
!
!------ calculate vortex panel contribution to Psi
            dxinv = 1.0/(x1-x2)
            psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
            psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
            psx1 = 0.5*g1
            psx2 = -(.5*g2)
            psyy = t1 - t2
!
            pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
            pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
            pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
            gsum1 = gamu(jp, 1) + gamu(jo, 1)
            gsum2 = gamu(jp, 2) + gamu(jo, 2)
            gdif1 = gamu(jp, 1) - gamu(jo, 1)
            gdif2 = gamu(jp, 2) - gamu(jo, 2)
!
            gsum = gam(jp) + gam(jo)
            gdif = gam(jp) - gam(jo)
!
            psi = psi - qopi*(psis*gsum+psid*gdif)
!
!------ dPsi/dGam
            dzdg(jo) = dzdg(jo) - qopi*(psis-psid)
            dzdg(jp) = dzdg(jp) - qopi*(psis+psid)
!
!------ dPsi/dni
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
            psi_ni = psi_ni - qopi*(gsum*psni+gdif*pdni)
!
            qtan1 = qtan1 - qopi*(gsum1*psni+gdif1*pdni)
            qtan2 = qtan2 - qopi*(gsum2*psni+gdif2*pdni)
!
            dqdg(jo) = dqdg(jo) - qopi*(psni-pdni)
            dqdg(jp) = dqdg(jp) - qopi*(psni+pdni)
!
            IF (geolin) THEN
!
!------- dPsi/dn
              dzdn(jo) = dzdn(jo) - qopi*gsum*(psx1*x1o+psx2*x2o+psyy*&
&               yyo) - qopi*gdif*(pdx1*x1o+pdx2*x2o+pdyy*yyo)
              dzdn(jp) = dzdn(jp) - qopi*gsum*(psx1*x1p+psx2*x2p+psyy*&
&               yyp) - qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
              z_qdof0 = z_qdof0 - qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&               qf0(jp))
              z_qdof1 = z_qdof1 - qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&               qf1(jp))
              z_qdof2 = z_qdof2 - qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&               qf2(jp))
              z_qdof3 = z_qdof3 - qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&               qf3(jp))
            END IF
          END IF
        END IF
      END DO
!
!
!
 120  psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
      pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
      psigx1 = -(t1-apan)
      psigx2 = t2 - apan
      psigyy = 0.5*(g1-g2)
      pgamx1 = 0.5*g1
      pgamx2 = -(.5*g2)
      pgamyy = t1 - t2
!
      psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
      sigte1 = 0.5*scs*(gamu(jp, 1)-gamu(jo, 1))
      sigte2 = 0.5*scs*(gamu(jp, 2)-gamu(jo, 2))
      gamte1 = -(.5*sds*(gamu(jp, 1)-gamu(jo, 1)))
      gamte2 = -(.5*sds*(gamu(jp, 2)-gamu(jo, 2)))
!
      sigte = 0.5*scs*(gam(jp)-gam(jo))
      gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
      psi = psi + hopi*(psig*sigte-pgam*gamte)
!
!---- dPsi/dGam
      dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
      dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
      dzdg(jo) = dzdg(jo) - hopi*pgam*sds*0.5
      dzdg(jp) = dzdg(jp) + hopi*pgam*sds*0.5
!
!---- dPsi/dni
      psi_ni = psi_ni + hopi*(psigni*sigte-pgamni*gamte)
!
      qtan1 = qtan1 + hopi*(psigni*sigte1-pgamni*gamte1)
      qtan2 = qtan2 + hopi*(psigni*sigte2-pgamni*gamte2)
!
      dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs+pgamni*0.5*sds)
      dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs+pgamni*0.5*sds)
!
      IF (geolin) THEN
!
!----- dPsi/dn
        dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&         sigte - hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
        dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&         sigte - hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
        z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs + hopi*&
&         pgam*0.5*(qf0(jp)-qf0(jo))*sds
        z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs + hopi*&
&         pgam*0.5*(qf1(jp)-qf1(jo))*sds
        z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs + hopi*&
&         pgam*0.5*(qf2(jp)-qf2(jo))*sds
        z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs + hopi*&
&         pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
      END IF
    END IF
99999 CONTINUE
  END SUBROUTINE PSILIN

!  Differentiation of psilin_xw in reverse (adjoint) mode, forward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PS
!ILIN_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET 
!CLCALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInF
!ile):
!   gradient     of useful results: dqdm dste x y ante aste dzdm
!                alfa apanel dqdg gam xi yi psi_ni
!   with respect to varying inputs: dqdm dste x y ante aste dzdm
!                alfa apanel dqdg gam xi yi
!*** XFOILAD: copy of PSILIN without the QTAN1/QTAN2 (GAMU) part, used by
!    XYWAKE. With the shared PSILIN, Tapenade judged GAMU inactive inside
!    XYWAKE and reset its derivative, losing the d(QINVU wake)/d(geometry)
!    contribution computed later by QWCALC.
  SUBROUTINE PSILIN_XW_FWD(i, xi, yi, nxi, nyi, psi, psi_ni, geolin, &
&   siglin)
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    LOGICAL :: geolin, siglin
    INTEGER :: i
    REAL :: nxi, nyi, psi, psi_ni, xi, yi
! intent (in) Geolin, I, Nxi, Nyi, Siglin, Xi, Yi
! intent (inout) Psi, Psi_ni
!
! Local variables
!
    REAL :: apan, dsim, dsio, dsip, dsm, dso, dsp, dxinv, g0, g1, g2, &
&   gamte1, gamte2, gdif, gdif1, gdif2, gsum, gsum1, gsum2, nxo, nxp, &
&   nyo, nyp, pdif, pdni, pdx0, pdx1, pdx2, pdyy, pgam, pgamni, pgamx1, &
&   pgamx2, pgamyy, psid, psig, psigni, psigx1, psigx2, psigyy, psis, &
&   psni, psum, psx0, psx1, psx2, psyy, qtanm, rs0, rs1, rs2, rx1, rx2, &
&   ry1, ry2, scs, sdif, sds, seps, sgn, sigte1, sigte2, ssum, sx, sy, &
&   t0, t1, t2, x0, x1, x1i, x1o, x1p, x2, x2i, x2o, x2p, xjo
    REAL :: xjp, yjo
    INTEGER :: io, jm, jo, jp, jq
    REAL :: yjp, yy, yyi, yyo, yyp
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC SQRT
    INTRINSIC EPSILON
    INTRINSIC SIGN
    INTRINSIC LOG
    INTRINSIC ATAN2
    REAL :: result1
    REAL :: result2
    INTEGER :: ad_count
    INTEGER :: ad_count0
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------------------------
!     Calculates current streamfunction Psi at panel node or wake node
!     I due to freestream and all bound vorticity Gam on the airfoil.
!     Sensitivities of Psi with respect to alpha (Z_ALFA) and inverse
!     Qspec DOFs (Z_QDOF0,Z_QDOF1) which influence Gam in inverse cases.
!     Also calculates the sensitivity vector dPsi/dGam (DZDG).
!
!     If SIGLIN=True, then Psi includes the effects of the viscous
!     source distribution Sig and the sensitivity vector dPsi/dSig
!     (DZDM) is calculated.
!
!     If GEOLIN=True, then the geometric sensitivity vector dPsi/dn
!     is calculated, where n is the normal motion of the jth node.
!
!          Airfoil:  1   < I < N
!          Wake:     N+1 < I < N+NW
!-----------------------------------------------------------------------
!
!---- distance tolerance for determining if two points are the same
    seps = (s(n)-s(1))*1.0e-5
!
    io = i
!
    CALL PUSHREAL8(cosa)
    cosa = COS(alfa)
    CALL PUSHREAL8(sina)
    sina = SIN(alfa)
!
    DO jo=1,n
      dzdg(jo) = 0.0
      dqdg(jo) = 0.0
    END DO
!
    DO jo=1,n
      dzdm(jo) = 0.0
      dqdm(jo) = 0.0
    END DO
!
!
    CALL PUSHREAL8(psi_ni)
    psi_ni = 0.
!
!
    IF (sharp) THEN
      CALL PUSHCONTROL1B(1)
      scs = 1.0
      sds = 0.0
    ELSE
      scs = ante/dste
      sds = aste/dste
      CALL PUSHCONTROL1B(0)
    END IF
    CALL PUSHINTEGER4(jo)
    ad_count = 1
!
    DO jo=1,n
      CALL PUSHINTEGER4(jp)
      jp = jo + 1
!
      CALL PUSHINTEGER4(jm)
      jm = jo - 1
      CALL PUSHINTEGER4(jq)
      jq = jp + 1
!
      IF (jo .EQ. 1) THEN
        CALL PUSHCONTROL2B(0)
        jm = jo
      ELSE IF (jo .EQ. n - 1) THEN
        CALL PUSHCONTROL2B(1)
        jq = jp
      ELSE IF (jo .EQ. n) THEN
        jp = 1
        IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) THEN
          GOTO 110
        ELSE
          CALL PUSHCONTROL2B(2)
        END IF
      ELSE
        CALL PUSHCONTROL2B(3)
      END IF
!
      CALL PUSHREAL8(dso)
      dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then 
      result1 = EPSILON(0.)
      result2 = EPSILON(0.)
      IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) THEN
!
        CALL PUSHREAL8(dsio)
        dsio = 1.0/dso
!
        CALL PUSHREAL8(apan)
        apan = apanel(jo)
!
        CALL PUSHREAL8(rx1)
        rx1 = xi - x(jo)
        CALL PUSHREAL8(ry1)
        ry1 = yi - y(jo)
        CALL PUSHREAL8(rx2)
        rx2 = xi - x(jp)
        CALL PUSHREAL8(ry2)
        ry2 = yi - y(jp)
!
        CALL PUSHREAL8(sx)
        sx = (x(jp)-x(jo))*dsio
        CALL PUSHREAL8(sy)
        sy = (y(jp)-y(jo))*dsio
!
        CALL PUSHREAL8(x1)
        x1 = sx*rx1 + sy*ry1
        CALL PUSHREAL8(x2)
        x2 = sx*rx2 + sy*ry2
        CALL PUSHREAL8(yy)
        yy = sx*ry1 - sy*rx1
!
        rs1 = rx1*rx1 + ry1*ry1
        rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
        IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
          CALL PUSHREAL8(sgn)
          sgn = 1.0
          CALL PUSHCONTROL1B(0)
        ELSE
!------- make sure arctan falls between  -/+  Pi/2
          CALL PUSHREAL8(sgn)
          sgn = SIGN(1.0, yy)
          CALL PUSHCONTROL1B(1)
        END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
        IF (io .NE. jo .AND. rs1 .GT. 0.0) THEN
          CALL PUSHREAL8(g1)
          g1 = LOG(rs1)
          CALL PUSHREAL8(t1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(g1)
          g1 = 0.0
          CALL PUSHREAL8(t1)
          t1 = 0.0
          CALL PUSHCONTROL1B(1)
        END IF
!
        IF (io .NE. jp .AND. rs2 .GT. 0.0) THEN
          CALL PUSHREAL8(g2)
          g2 = LOG(rs2)
          CALL PUSHREAL8(t2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
          CALL PUSHCONTROL1B(0)
        ELSE
          CALL PUSHREAL8(g2)
          g2 = 0.0
          CALL PUSHREAL8(t2)
          t2 = 0.0
          CALL PUSHCONTROL1B(1)
        END IF
!
        CALL PUSHREAL8(x1i)
        x1i = sx*nxi + sy*nyi
        CALL PUSHREAL8(x2i)
        x2i = sx*nxi + sy*nyi
        CALL PUSHREAL8(yyi)
        yyi = sx*nyi - sy*nxi
!
!
        IF (jo .EQ. n) THEN
          GOTO 120
        ELSE
!
          IF (siglin) THEN
!
!------- set up midpoint quantities
            x0 = 0.5*(x1+x2)
            rs0 = x0*x0 + yy*yy
            CALL PUSHREAL8(g0)
            g0 = LOG(rs0)
            CALL PUSHREAL8(t0)
            t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
            dxinv = 1.0/(x1-x0)
            CALL PUSHREAL8(psum)
            psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
            CALL PUSHREAL8(pdif)
            pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*yy)&
&             *dxinv
!
            psx1 = -(t1-apan)
            psx0 = t0 - apan
            psyy = 0.5*(g1-g0)
!
            pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
            CALL PUSHREAL8(pdx0)
            pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
            pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
            CALL PUSHREAL8(dsm)
            dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
            dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
            ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
            sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
!
!------- dPsi/dm
            dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
            dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-dsim&
&             ))
!
!------- dPsi/dni
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
!
            dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
            dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-dsim&
&             ))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
            dxinv = 1.0/(x0-x2)
            CALL PUSHREAL8(psum)
            psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
            CALL PUSHREAL8(pdif)
            pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*yy)&
&             *dxinv
!
            psx0 = -(t0-apan)
            psx2 = t2 - apan
            psyy = 0.5*(g0-g2)
!
            CALL PUSHREAL8(pdx0)
            pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
            pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
            CALL PUSHREAL8(pdyy)
            pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
            CALL PUSHREAL8(dsp)
            dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
            dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
            ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
            sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
!
!------- dPsi/dm
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip-&
&             dsio))
            dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
            dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
            psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
            pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
!
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip-&
&             dsio))
            dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
            dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
            CALL PUSHCONTROL1B(0)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
!
!------ calculate vortex panel contribution to Psi
          dxinv = 1.0/(x1-x2)
          CALL PUSHREAL8(psis)
          psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
          CALL PUSHREAL8(psid)
          psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
          psx1 = 0.5*g1
          psx2 = -(.5*g2)
          psyy = t1 - t2
!
          CALL PUSHREAL8(pdx1)
          pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
          CALL PUSHREAL8(pdx2)
          pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
          CALL PUSHREAL8(pdyy)
          pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
!
          gsum = gam(jp) + gam(jo)
          gdif = gam(jp) - gam(jo)
!
!
!------ dPsi/dGam
          dzdg(jo) = dzdg(jo) + qopi*(psis-psid)
          dzdg(jp) = dzdg(jp) + qopi*(psis+psid)
!
!------ dPsi/dni
          psni = psx1*x1i + psx2*x2i + psyy*yyi
          pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
          psi_ni = psi_ni + qopi*(gsum*psni+gdif*pdni)
!
!
          dqdg(jo) = dqdg(jo) + qopi*(psni-pdni)
          dqdg(jp) = dqdg(jp) + qopi*(psni+pdni)
!
          IF (geolin) THEN
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(1)
          END IF
        END IF
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
      CALL PUSHINTEGER4(jo)
      ad_count = ad_count + 1
    END DO
    CALL PUSHCONTROL2B(0)
    CALL PUSHINTEGER4(ad_count)
    GOTO 130
 110 CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL1B(0)
    GOTO 100
 120 CALL PUSHCONTROL2B(2)
    CALL PUSHINTEGER4(ad_count)
!
!
!
 130 psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
    pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
    psigx1 = -(t1-apan)
    psigx2 = t2 - apan
    psigyy = 0.5*(g1-g2)
    pgamx1 = 0.5*g1
    pgamx2 = -(.5*g2)
    pgamyy = t1 - t2
!
    psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
    pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
!
    CALL PUSHREAL8(sigte)
    sigte = 0.5*scs*(gam(jp)-gam(jo))
    CALL PUSHREAL8(gamte)
    gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
!
!---- dPsi/dGam
    dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
    dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
    dzdg(jo) = dzdg(jo) + hopi*pgam*sds*0.5
    dzdg(jp) = dzdg(jp) - hopi*pgam*sds*0.5
!
!---- dPsi/dni
    psi_ni = psi_ni + hopi*(psigni*sigte+pgamni*gamte)
!
!
    dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs-pgamni*0.5*sds)
    dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs-pgamni*0.5*sds)
!
    IF (geolin) THEN
      CALL PUSHCONTROL1B(1)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!
!**** Freestream terms
!
!---- dPsi/dn
 100 psi_ni = psi_ni + qinf*(cosa*nyi-sina*nxi)
!
!
!---- dPsi/dQinf
!
!---- dPsi/dalfa
!
    IF (.NOT.limage) THEN
      CALL PUSHREAL8(scs)
      CALL PUSHINTEGER4(jq)
      CALL PUSHINTEGER4(jp)
      CALL PUSHINTEGER4(jo)
      CALL PUSHINTEGER4(jm)
      CALL PUSHREAL8(sy)
      CALL PUSHREAL8(sx)
      CALL PUSHREAL8(dsio)
      CALL PUSHREAL8(dsp)
      CALL PUSHREAL8(psis)
      CALL PUSHREAL8(apan)
      CALL PUSHREAL8(dso)
      CALL PUSHREAL8(x2i)
      CALL PUSHREAL8(dsm)
      CALL PUSHREAL8(yy)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(rs2)
      CALL PUSHREAL8(x1)
      CALL PUSHREAL8(rs1)
      CALL PUSHREAL8(psid)
      CALL PUSHREAL8(pdx0)
      CALL PUSHREAL8(ry2)
      CALL PUSHREAL8(ry1)
      CALL PUSHREAL8(pdif)
      CALL PUSHREAL8(t2)
      CALL PUSHREAL8(t1)
      CALL PUSHREAL8(t0)
      CALL PUSHREAL8(x1i)
      CALL PUSHREAL8(g2)
      CALL PUSHREAL8(psum)
      CALL PUSHREAL8(g1)
      CALL PUSHREAL8(g0)
      CALL PUSHREAL8(yyi)
      CALL PUSHREAL8(sds)
      CALL PUSHREAL8(rx2)
      CALL PUSHREAL8(rx1)
      CALL PUSHREAL8(sgn)
      CALL PUSHCONTROL2B(0)
    ELSE
      CALL PUSHINTEGER4(jo)
      ad_count0 = 1
!
!
!
      DO jo=1,n
        CALL PUSHINTEGER4(jp)
        jp = jo + 1
!
        CALL PUSHINTEGER4(jm)
        jm = jo - 1
        CALL PUSHINTEGER4(jq)
        jq = jp + 1
!
        IF (jo .EQ. 1) THEN
          CALL PUSHCONTROL2B(0)
          jm = jo
        ELSE IF (jo .EQ. n - 1) THEN
          CALL PUSHCONTROL2B(1)
          jq = jp
        ELSE IF (jo .EQ. n) THEN
          jp = 1
          IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) THEN
            GOTO 140
          ELSE
            CALL PUSHCONTROL2B(2)
          END IF
        ELSE
          CALL PUSHCONTROL2B(3)
        END IF
!
        CALL PUSHREAL8(dso)
        dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then
        result1 = EPSILON(0.)
        result2 = EPSILON(0.)
        IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) &
&       THEN
!
          CALL PUSHREAL8(dsio)
          dsio = 1.0/dso
!
!cc     APAN = APANEL(JO)
          CALL PUSHREAL8(apan)
          apan = pi - apanel(jo) + 2.0*alfa
!
          CALL PUSHREAL8(xjo)
          xjo = x(jo) + 2.0*(yimage+y(jo))*sina
          CALL PUSHREAL8(yjo)
          yjo = y(jo) - 2.0*(yimage+y(jo))*cosa
          CALL PUSHREAL8(xjp)
          xjp = x(jp) + 2.0*(yimage+y(jp))*sina
          CALL PUSHREAL8(yjp)
          yjp = y(jp) - 2.0*(yimage+y(jp))*cosa
!
          CALL PUSHREAL8(rx1)
          rx1 = xi - xjo
          CALL PUSHREAL8(ry1)
          ry1 = yi - yjo
          CALL PUSHREAL8(rx2)
          rx2 = xi - xjp
          CALL PUSHREAL8(ry2)
          ry2 = yi - yjp
!
          CALL PUSHREAL8(sx)
          sx = (xjp-xjo)*dsio
          CALL PUSHREAL8(sy)
          sy = (yjp-yjo)*dsio
!
          CALL PUSHREAL8(x1)
          x1 = sx*rx1 + sy*ry1
          CALL PUSHREAL8(x2)
          x2 = sx*rx2 + sy*ry2
          CALL PUSHREAL8(yy)
          yy = sx*ry1 - sy*rx1
!
          CALL PUSHREAL8(rs1)
          rs1 = rx1*rx1 + ry1*ry1
          CALL PUSHREAL8(rs2)
          rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
          IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
            CALL PUSHREAL8(sgn)
            sgn = 1.0
            CALL PUSHCONTROL1B(0)
          ELSE
!------- make sure arctan falls between  -/+  Pi/2
            CALL PUSHREAL8(sgn)
            sgn = SIGN(1.0, yy)
            CALL PUSHCONTROL1B(1)
          END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
          CALL PUSHREAL8(g1)
          g1 = LOG(rs1)
          CALL PUSHREAL8(t1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
!
          CALL PUSHREAL8(g2)
          g2 = LOG(rs2)
          CALL PUSHREAL8(t2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
!
          CALL PUSHREAL8(x1i)
          x1i = sx*nxi + sy*nyi
          CALL PUSHREAL8(x2i)
          x2i = sx*nxi + sy*nyi
          CALL PUSHREAL8(yyi)
          yyi = sx*nyi - sy*nxi
!
!
          IF (jo .EQ. n) THEN
            GOTO 150
          ELSE
!
            IF (siglin) THEN
!
!------- set up midpoint quantities
              x0 = 0.5*(x1+x2)
              rs0 = x0*x0 + yy*yy
              CALL PUSHREAL8(g0)
              g0 = LOG(rs0)
              CALL PUSHREAL8(t0)
              t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
              dxinv = 1.0/(x1-x0)
              CALL PUSHREAL8(psum)
              psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
              CALL PUSHREAL8(pdif)
              pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*&
&               yy)*dxinv
!
              psx1 = -(t1-apan)
              psx0 = t0 - apan
              psyy = 0.5*(g1-g0)
!
              pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
              CALL PUSHREAL8(pdx0)
              pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
              pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
              CALL PUSHREAL8(dsm)
              dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
              dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
              ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
              sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
!
!------- dPsi/dm
              dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
              dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-&
&               dsim))
!
!------- dPsi/dni
              psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
              pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
!
              dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
              dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-&
&               dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
              dxinv = 1.0/(x0-x2)
              CALL PUSHREAL8(psum)
              psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
              CALL PUSHREAL8(pdif)
              pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*&
&               yy)*dxinv
!
              psx0 = -(t0-apan)
              psx2 = t2 - apan
              psyy = 0.5*(g0-g2)
!
              CALL PUSHREAL8(pdx0)
              pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
              pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
              CALL PUSHREAL8(pdyy)
              pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
              CALL PUSHREAL8(dsp)
              dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
              dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
              ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
              sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
!
!------- dPsi/dm
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip&
&               -dsio))
              dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
              dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
!
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip&
&               -dsio))
              dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
              dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
              CALL PUSHCONTROL1B(0)
            ELSE
              CALL PUSHCONTROL1B(1)
            END IF
!
!------ calculate vortex panel contribution to Psi
            dxinv = 1.0/(x1-x2)
            CALL PUSHREAL8(psis)
            psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
            CALL PUSHREAL8(psid)
            psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
            psx1 = 0.5*g1
            psx2 = -(.5*g2)
            psyy = t1 - t2
!
            CALL PUSHREAL8(pdx1)
            pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
            CALL PUSHREAL8(pdx2)
            pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
            CALL PUSHREAL8(pdyy)
            pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
!
            gsum = gam(jp) + gam(jo)
            gdif = gam(jp) - gam(jo)
!
!
!------ dPsi/dGam
            dzdg(jo) = dzdg(jo) - qopi*(psis-psid)
            dzdg(jp) = dzdg(jp) - qopi*(psis+psid)
!
!------ dPsi/dni
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
            psi_ni = psi_ni - qopi*(gsum*psni+gdif*pdni)
!
!
            dqdg(jo) = dqdg(jo) - qopi*(psni-pdni)
            dqdg(jp) = dqdg(jp) - qopi*(psni+pdni)
!
            CALL PUSHCONTROL1B(1)
          END IF
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        CALL PUSHINTEGER4(jo)
        ad_count0 = ad_count0 + 1
      END DO
      CALL PUSHCONTROL2B(0)
      CALL PUSHINTEGER4(ad_count0)
      GOTO 160
 140  CALL PUSHCONTROL2B(1)
      CALL PUSHINTEGER4(ad_count0)
      CALL PUSHREAL8(scs)
      CALL PUSHREAL8(sy)
      CALL PUSHREAL8(sx)
      CALL PUSHREAL8(dsio)
      CALL PUSHREAL8(yjp)
      CALL PUSHREAL8(yjo)
      CALL PUSHREAL8(dsp)
      CALL PUSHREAL8(psis)
      CALL PUSHREAL8(apan)
      CALL PUSHREAL8(dso)
      CALL PUSHREAL8(x2i)
      CALL PUSHREAL8(dsm)
      CALL PUSHREAL8(yy)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(rs2)
      CALL PUSHREAL8(x1)
      CALL PUSHREAL8(rs1)
      CALL PUSHREAL8(psid)
      CALL PUSHREAL8(pdx0)
      CALL PUSHREAL8(ry2)
      CALL PUSHREAL8(ry1)
      CALL PUSHREAL8(pdif)
      CALL PUSHREAL8(t2)
      CALL PUSHREAL8(t1)
      CALL PUSHREAL8(t0)
      CALL PUSHREAL8(x1i)
      CALL PUSHREAL8(g2)
      CALL PUSHREAL8(psum)
      CALL PUSHREAL8(g1)
      CALL PUSHREAL8(g0)
      CALL PUSHREAL8(yyi)
      CALL PUSHREAL8(sds)
      CALL PUSHREAL8(rx2)
      CALL PUSHREAL8(rx1)
      CALL PUSHREAL8(sgn)
      CALL PUSHREAL8(xjp)
      CALL PUSHREAL8(xjo)
      CALL PUSHCONTROL2B(1)
      GOTO 170
 150  CALL PUSHCONTROL2B(2)
      CALL PUSHINTEGER4(ad_count0)
!
!
!
 160  psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
      pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
      psigx1 = -(t1-apan)
      psigx2 = t2 - apan
      psigyy = 0.5*(g1-g2)
      pgamx1 = 0.5*g1
      pgamx2 = -(.5*g2)
      pgamyy = t1 - t2
!
      psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
!
      CALL PUSHREAL8(sigte)
      sigte = 0.5*scs*(gam(jp)-gam(jo))
      CALL PUSHREAL8(gamte)
      gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
!
!---- dPsi/dGam
      dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
      dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
      dzdg(jo) = dzdg(jo) - hopi*pgam*sds*0.5
      dzdg(jp) = dzdg(jp) + hopi*pgam*sds*0.5
!
!---- dPsi/dni
      psi_ni = psi_ni + hopi*(psigni*sigte-pgamni*gamte)
!
!
      dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs+pgamni*0.5*sds)
      dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs+pgamni*0.5*sds)
!
      CALL PUSHREAL8(scs)
      CALL PUSHINTEGER4(jq)
      CALL PUSHINTEGER4(jp)
      CALL PUSHINTEGER4(jo)
      CALL PUSHINTEGER4(jm)
      CALL PUSHREAL8(sy)
      CALL PUSHREAL8(sx)
      CALL PUSHREAL8(dsio)
      CALL PUSHREAL8(yjp)
      CALL PUSHREAL8(yjo)
      CALL PUSHREAL8(dsp)
      CALL PUSHREAL8(psis)
      CALL PUSHREAL8(apan)
      CALL PUSHREAL8(dso)
      CALL PUSHREAL8(x2i)
      CALL PUSHREAL8(dsm)
      CALL PUSHREAL8(yy)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(rs2)
      CALL PUSHREAL8(x1)
      CALL PUSHREAL8(rs1)
      CALL PUSHREAL8(psid)
      CALL PUSHREAL8(pdx0)
      CALL PUSHREAL8(ry2)
      CALL PUSHREAL8(ry1)
      CALL PUSHREAL8(pdif)
      CALL PUSHREAL8(t2)
      CALL PUSHREAL8(t1)
      CALL PUSHREAL8(t0)
      CALL PUSHREAL8(x1i)
      CALL PUSHREAL8(g2)
      CALL PUSHREAL8(psum)
      CALL PUSHREAL8(g1)
      CALL PUSHREAL8(g0)
      CALL PUSHREAL8(yyi)
      CALL PUSHREAL8(sds)
      CALL PUSHREAL8(rx2)
      CALL PUSHREAL8(rx1)
      CALL PUSHREAL8(sgn)
      CALL PUSHREAL8(xjp)
      CALL PUSHREAL8(xjo)
      CALL PUSHCONTROL2B(2)
    END IF
 170 CONTINUE
  END SUBROUTINE PSILIN_XW_FWD

!  Differentiation of psilin_xw in reverse (adjoint) mode, backward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN P
!SILIN_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET
! CLCALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesIn
!File):
!   gradient     of useful results: dqdm dste x y ante aste dzdm
!                alfa apanel dqdg gam xi yi psi_ni
!   with respect to varying inputs: dqdm dste x y ante aste dzdm
!                alfa apanel dqdg gam xi yi
!*** XFOILAD: copy of PSILIN without the QTAN1/QTAN2 (GAMU) part, used by
!    XYWAKE. With the shared PSILIN, Tapenade judged GAMU inactive inside
!    XYWAKE and reset its derivative, losing the d(QINVU wake)/d(geometry)
!    contribution computed later by QWCALC.
  SUBROUTINE PSILIN_XW_BWD(i, xi, xib, yi, yib, nxi, nyi, psi, psi_ni, &
&   psi_nib, geolin, siglin)
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
    LOGICAL :: geolin, siglin
    INTEGER :: i
    REAL :: nxi, nyi, psi, psi_ni, xi, yi
    REAL :: psi_nib, xib, yib
    REAL :: apan, dsim, dsio, dsip, dsm, dso, dsp, dxinv, g0, g1, g2, &
&   gamte1, gamte2, gdif, gdif1, gdif2, gsum, gsum1, gsum2, nxo, nxp, &
&   nyo, nyp, pdif, pdni, pdx0, pdx1, pdx2, pdyy, pgam, pgamni, pgamx1, &
&   pgamx2, pgamyy, psid, psig, psigni, psigx1, psigx2, psigyy, psis, &
&   psni, psum, psx0, psx1, psx2, psyy, qtanm, rs0, rs1, rs2, rx1, rx2, &
&   ry1, ry2, scs, sdif, sds, seps, sgn, sigte1, sigte2, ssum, sx, sy, &
&   t0, t1, t2, x0, x1, x1i, x1o, x1p, x2, x2i, x2o, x2p, xjo
    REAL :: xjp, yjo
    REAL :: apanb, dsimb, dsiob, dsipb, dsmb, dsob, dspb, dxinvb, g0b, &
&   g1b, g2b, gdifb, gsumb, pdifb, pdnib, pdx0b, pdx1b, pdx2b, pdyyb, &
&   pgamnib, pgamx1b, pgamx2b, pgamyyb, psidb, psignib, psigx1b, psigx2b&
&   , psigyyb, psisb, psnib, psumb, psx0b, psx1b, psx2b, psyyb, rs0b, &
&   rs1b, rs2b, rx1b, rx2b, ry1b, ry2b, scsb, sdifb, sdsb, ssumb, sxb, &
&   syb, t0b, t1b, t2b, x0b, x1b, x1ib, x2b, x2ib, xjob, xjpb, yjob
    INTEGER :: io, jm, jo, jp, jq
    REAL :: yjp, yy, yyi, yyo, yyp
    REAL :: yjpb, yyb, yyib
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC SQRT
    INTRINSIC EPSILON
    INTRINSIC SIGN
    INTRINSIC LOG
    INTRINSIC ATAN2
    REAL :: result1
    REAL :: result2
    REAL :: tempb
    REAL :: tempb0
    REAL :: tempb1
    INTEGER :: branch
    INTEGER :: ad_count
    INTEGER :: i0
    INTEGER :: ad_count0
    INTEGER :: i1
    CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(sgn)
      CALL POPREAL8(rx1)
      CALL POPREAL8(rx2)
      CALL POPREAL8(sds)
      CALL POPREAL8(yyi)
      CALL POPREAL8(g0)
      CALL POPREAL8(g1)
      CALL POPREAL8(psum)
      CALL POPREAL8(g2)
      CALL POPREAL8(x1i)
      CALL POPREAL8(t0)
      CALL POPREAL8(t1)
      CALL POPREAL8(t2)
      CALL POPREAL8(pdif)
      CALL POPREAL8(ry1)
      CALL POPREAL8(ry2)
      CALL POPREAL8(pdx0)
      CALL POPREAL8(psid)
      CALL POPREAL8(rs1)
      CALL POPREAL8(x1)
      CALL POPREAL8(rs2)
      CALL POPREAL8(x2)
      CALL POPREAL8(yy)
      CALL POPREAL8(dsm)
      CALL POPREAL8(x2i)
      CALL POPREAL8(dso)
      CALL POPREAL8(apan)
      CALL POPREAL8(psis)
      CALL POPREAL8(dsp)
      CALL POPREAL8(dsio)
      CALL POPREAL8(sx)
      CALL POPREAL8(sy)
      CALL POPINTEGER4(jm)
      CALL POPINTEGER4(jo)
      CALL POPINTEGER4(jp)
      CALL POPINTEGER4(jq)
      CALL POPREAL8(scs)
      cosab = 0.0_8
      sinab = 0.0_8
      sdsb = 0.0_8
      yyib = 0.0_8
      g1b = 0.0_8
      g2b = 0.0_8
      x1ib = 0.0_8
      t1b = 0.0_8
      t2b = 0.0_8
      x2ib = 0.0_8
      apanb = 0.0_8
      scsb = 0.0_8
    ELSE
      IF (branch .EQ. 1) THEN
        CALL POPREAL8(xjo)
        CALL POPREAL8(xjp)
        CALL POPREAL8(sgn)
        CALL POPREAL8(rx1)
        CALL POPREAL8(rx2)
        CALL POPREAL8(sds)
        CALL POPREAL8(yyi)
        CALL POPREAL8(g0)
        CALL POPREAL8(g1)
        CALL POPREAL8(psum)
        CALL POPREAL8(g2)
        CALL POPREAL8(x1i)
        CALL POPREAL8(t0)
        CALL POPREAL8(t1)
        CALL POPREAL8(t2)
        CALL POPREAL8(pdif)
        CALL POPREAL8(ry1)
        CALL POPREAL8(ry2)
        CALL POPREAL8(pdx0)
        CALL POPREAL8(psid)
        CALL POPREAL8(rs1)
        CALL POPREAL8(x1)
        CALL POPREAL8(rs2)
        CALL POPREAL8(x2)
        CALL POPREAL8(yy)
        CALL POPREAL8(dsm)
        CALL POPREAL8(x2i)
        CALL POPREAL8(dso)
        CALL POPREAL8(apan)
        CALL POPREAL8(psis)
        CALL POPREAL8(dsp)
        CALL POPREAL8(yjo)
        CALL POPREAL8(yjp)
        CALL POPREAL8(dsio)
        CALL POPREAL8(sx)
        CALL POPREAL8(sy)
        CALL POPREAL8(scs)
      ELSE
        CALL POPREAL8(xjo)
        CALL POPREAL8(xjp)
        CALL POPREAL8(sgn)
        CALL POPREAL8(rx1)
        CALL POPREAL8(rx2)
        CALL POPREAL8(sds)
        CALL POPREAL8(yyi)
        CALL POPREAL8(g0)
        CALL POPREAL8(g1)
        CALL POPREAL8(psum)
        CALL POPREAL8(g2)
        CALL POPREAL8(x1i)
        CALL POPREAL8(t0)
        CALL POPREAL8(t1)
        CALL POPREAL8(t2)
        CALL POPREAL8(pdif)
        CALL POPREAL8(ry1)
        CALL POPREAL8(ry2)
        CALL POPREAL8(pdx0)
        CALL POPREAL8(psid)
        CALL POPREAL8(rs1)
        CALL POPREAL8(x1)
        CALL POPREAL8(rs2)
        CALL POPREAL8(x2)
        CALL POPREAL8(yy)
        CALL POPREAL8(dsm)
        CALL POPREAL8(x2i)
        CALL POPREAL8(dso)
        CALL POPREAL8(apan)
        CALL POPREAL8(psis)
        CALL POPREAL8(dsp)
        CALL POPREAL8(yjo)
        CALL POPREAL8(yjp)
        CALL POPREAL8(dsio)
        CALL POPREAL8(sx)
        CALL POPREAL8(sy)
        CALL POPINTEGER4(jm)
        CALL POPINTEGER4(jo)
        CALL POPINTEGER4(jp)
        CALL POPINTEGER4(jq)
        CALL POPREAL8(scs)
        pgamx1 = 0.5*g1
        pgamx2 = -(.5*g2)
        pgamyy = t1 - t2
        psigx1 = -(t1-apan)
        psigx2 = t2 - apan
        psigyy = 0.5*(g1-g2)
        pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
        psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
        tempb1 = hopi*dqdgb(jp)
        psignib = scs*0.5*tempb1
        scsb = psigni*0.5*tempb1
        pgamnib = sds*0.5*tempb1
        sdsb = pgamni*0.5*tempb1
        tempb1 = -(hopi*dqdgb(jo))
        psignib = psignib + scs*0.5*tempb1
        scsb = scsb + psigni*0.5*tempb1
        pgamnib = pgamnib + sds*0.5*tempb1
        sdsb = sdsb + pgamni*0.5*tempb1
        gamte = -(.5*sds*(gam(jp)-gam(jo)))
        sigte = 0.5*scs*(gam(jp)-gam(jo))
        tempb1 = hopi*psi_nib
        psignib = psignib + sigte*tempb1
        sigteb = psigni*tempb1
        pgamnib = pgamnib - gamte*tempb1
        gamteb = -(pgamni*tempb1)
        CALL POPREAL8(gamte)
        sdsb = sdsb - (gam(jp)-gam(jo))*.5*gamteb
        tempb1 = -(sds*.5*gamteb)
        gamb(jp) = gamb(jp) + tempb1
        gamb(jo) = gamb(jo) - tempb1
        CALL POPREAL8(sigte)
        scsb = scsb + (gam(jp)-gam(jo))*0.5*sigteb
        tempb1 = scs*0.5*sigteb
        gamb(jp) = gamb(jp) + tempb1
        gamb(jo) = gamb(jo) - tempb1
        pgamx1b = x1i*pgamnib
        x1ib = pgamx1*pgamnib + psigx1*psignib
        pgamx2b = x2i*pgamnib
        x2ib = pgamx2*pgamnib + psigx2*psignib
        pgamyyb = yyi*pgamnib
        yyib = pgamyy*pgamnib + psigyy*psignib
        psigx1b = x1i*psignib
        psigx2b = x2i*psignib
        psigyyb = yyi*psignib
        t1b = pgamyyb - psigx1b
        t2b = psigx2b - pgamyyb
        g2b = -(.5*pgamx2b) - 0.5*psigyyb
        g1b = 0.5*pgamx1b + 0.5*psigyyb
        apanb = psigx1b - psigx2b
      END IF
      CALL POPINTEGER4(ad_count0)
      DO i1=1,ad_count0
        IF (i1 .EQ. 1) THEN
          CALL POPCONTROL2B(branch)
          IF (branch .EQ. 0) THEN
            cosab = 0.0_8
            sinab = 0.0_8
            GOTO 120
          ELSE IF (branch .EQ. 1) THEN
            cosab = 0.0_8
            sinab = 0.0_8
            sdsb = 0.0_8
            yyib = 0.0_8
            g1b = 0.0_8
            g2b = 0.0_8
            x1ib = 0.0_8
            t1b = 0.0_8
            t2b = 0.0_8
            x2ib = 0.0_8
            apanb = 0.0_8
            scsb = 0.0_8
            GOTO 110
          ELSE
            cosab = 0.0_8
            sinab = 0.0_8
            rs1b = 0.0_8
            x1b = 0.0_8
            rs2b = 0.0_8
            x2b = 0.0_8
            yyb = 0.0_8
            dsiob = 0.0_8
          END IF
        ELSE
          CALL POPCONTROL1B(branch)
          IF (branch .EQ. 0) THEN
            dsob = 0.0_8
            GOTO 100
          ELSE
            rs2 = rx2*rx2 + ry2*ry2
            rs1 = rx1*rx1 + ry1*ry1
            tempb1 = -(qopi*psi_nib)
            gdif = gam(jp) - gam(jo)
            gsum = gam(jp) + gam(jo)
            dxinv = 1.0/(x1-x2)
            psx1 = 0.5*g1
            pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
            psx2 = -(.5*g2)
            pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
            psyy = t1 - t2
            pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            psnib = gsum*tempb1 - qopi*dqdgb(jp) - qopi*dqdgb(jo)
            pdnib = qopi*dqdgb(jo) - qopi*dqdgb(jp) + gdif*tempb1
            gsumb = psni*tempb1
            gdifb = pdni*tempb1
            pdx1b = x1i*pdnib
            x1ib = x1ib + pdx1*pdnib + psx1*psnib
            pdx2b = x2i*pdnib
            x2ib = x2ib + pdx2*pdnib + psx2*psnib
            pdyyb = yyi*pdnib
            yyib = yyib + pdyy*pdnib + psyy*psnib
            gamb(jp) = gamb(jp) + gdifb
            gamb(jo) = gamb(jo) - gdifb
            gamb(jp) = gamb(jp) + gsumb
            gamb(jo) = gamb(jo) + gsumb
            CALL POPREAL8(pdyy)
            tempb1 = dxinv*pdyyb
            psyyb = yyi*psnib + (x1+x2)*tempb1
            x1b = psyy*tempb1
            x2b = psyy*tempb1
            yyb = -((g1-g2)*tempb1)
            g1b = g1b - yy*tempb1
            g2b = g2b + yy*tempb1
            CALL POPREAL8(pdx2)
            tempb1 = dxinv*pdx2b
            psx2b = x2i*psnib + (x1+x2)*tempb1
            x1b = x1b + psx2*tempb1
            x2b = x2b + (psx2+g2)*tempb1
            psisb = tempb1
            g2b = g2b + x2*tempb1
            psidb = tempb1
            CALL POPREAL8(pdx1)
            tempb1 = dxinv*pdx1b
            psx1b = x1i*psnib + (x1+x2)*tempb1
            x1b = x1b + (psx1-g1)*tempb1
            x2b = x2b + psx1*tempb1
            psisb = psisb + tempb1
            g1b = g1b - x1*tempb1
            psidb = psidb - tempb1
            dxinvb = ((x1+x2)*psyy-yy*(g1-g2))*pdyyb + ((x1+x2)*psx2+&
&             psis+x2*g2+psid)*pdx2b + ((x1+x2)*psx1+psis-x1*g1-psid)*&
&             pdx1b + ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1**2-x2**2))*&
&             psidb
            CALL POPREAL8(psid)
            tempb1 = dxinv*psidb
            x1b = x1b + psis*tempb1
            x2b = x2b + psis*tempb1
            psisb = psisb + (x1+x2)*tempb1
            t1b = t1b + psyyb + yy*psisb
            t2b = t2b - psyyb - yy*psisb
            tempb0 = 0.5*tempb1
            g2b = g2b + rs2*tempb0 - .5*psx2b - x2*0.5*psisb
            g1b = g1b + 0.5*psx1b + x1*0.5*psisb - rs1*tempb0
            rs2b = g2*tempb0
            rs1b = -(g1*tempb0)
            CALL POPREAL8(psis)
            yyb = yyb + (t1-t2)*psisb
            tempb1 = -(dxinvb/(x1-x2)**2)
            x1b = x1b + 2*x1*tempb0 + (g1*0.5-1.0)*psisb + tempb1
            x2b = x2b + (1.0-g2*0.5)*psisb - 2*x2*tempb0 - tempb1
            CALL POPCONTROL1B(branch)
            IF (branch .EQ. 0) THEN
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
              psx0 = -(t0-apan)
              psx2 = t2 - apan
              psyy = 0.5*(g0-g2)
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              dsip = 1.0/dsp
              tempb1 = qopi*dqdmb(jq)
              psnib = dsip*tempb1
              dsipb = (psni+pdni)*tempb1
              pdnib = dsip*tempb1
              tempb1 = qopi*dqdmb(jp)
              psnib = psnib + dsio*tempb1
              dsiob = (psni-pdni)*tempb1
              pdnib = pdnib - dsio*tempb1
              tempb1 = qopi*dqdmb(jo)
              psnib = psnib - (dsip+dsio)*tempb1
              dsipb = dsipb - (psni+pdni)*tempb1
              dsiob = dsiob + (pdni-psni)*tempb1
              pdnib = pdnib - (dsip-dsio)*tempb1
              ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
              sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
              tempb1 = qopi*psi_nib
              psnib = psnib + ssum*tempb1
              ssumb = psni*tempb1
              pdnib = pdnib + sdif*tempb1
              sdifb = pdni*tempb1
              pdx0b = (x1i+x2i)*0.5*pdnib
              tempb1 = pdx0*0.5*pdnib
              pdx2b = x2i*pdnib
              x2ib = x2ib + pdx2*pdnib + tempb1
              pdyyb = yyi*pdnib
              yyib = yyib + pdyy*pdnib + psyy*psnib
              x1ib = x1ib + tempb1
              tempb1 = psx0*0.5*psnib
              x2ib = x2ib + psx2*psnib + tempb1
              x1ib = x1ib + tempb1
              tempb1 = qopi*dzdmb(jq)
              psumb = dsip*tempb1
              dsipb = dsipb + (psum+pdif)*tempb1
              pdifb = dsip*tempb1
              tempb1 = qopi*dzdmb(jp)
              psumb = psumb + dsio*tempb1
              dsiob = dsiob + (psum-pdif)*tempb1
              pdifb = pdifb - dsio*tempb1
              tempb1 = qopi*dzdmb(jo)
              psumb = psumb - (dsip+dsio)*tempb1
