            psx0 = -(t0-apan)
            psx2 = t2 - apan
            psyy = 0.5*(g0-g2)
            psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
            dsip = 1.0/dsp
            tempb1 = qopi*dqdmb(jq)
            psnib = dsip*tempb1
            dsipb = (psni+pdni)*tempb1
            pdnib = dsip*tempb1
            tempb1 = qopi*dqdmb(jp)
            psnib = psnib + dsio*tempb1
            dsiob = (psni-pdni)*tempb1
            pdnib = pdnib - dsio*tempb1
            tempb1 = qopi*dqdmb(jo)
            psnib = psnib - (dsip+dsio)*tempb1
            dsipb = dsipb - (psni+pdni)*tempb1
            dsiob = dsiob + (pdni-psni)*tempb1
            pdnib = pdnib - (dsip-dsio)*tempb1
            ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
            sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
            tempb1 = qopi*psi_nib
            psnib = psnib + ssum*tempb1
            ssumb = psni*tempb1
            pdnib = pdnib + sdif*tempb1
            sdifb = pdni*tempb1
            pdx0b = (x1i+x2i)*0.5*pdnib
            tempb1 = pdx0*0.5*pdnib
            pdx2b = x2i*pdnib
            x2ib = x2ib + pdx2*pdnib + tempb1
            pdyyb = yyi*pdnib
            yyib = yyib + pdyy*pdnib + psyy*psnib
            x1ib = x1ib + tempb1
            tempb1 = psx0*0.5*psnib
            x2ib = x2ib + psx2*psnib + tempb1
            x1ib = x1ib + tempb1
            tempb1 = qopi*dzdmb(jq)
            psumb = dsip*tempb1
            dsipb = dsipb + (psum+pdif)*tempb1
            pdifb = dsip*tempb1
            tempb1 = qopi*dzdmb(jp)
            psumb = psumb + dsio*tempb1
            dsiob = dsiob + (psum-pdif)*tempb1
            pdifb = pdifb - dsio*tempb1
            tempb1 = qopi*dzdmb(jo)
            psumb = psumb - (dsip+dsio)*tempb1
            dsipb = dsipb + (sig(jq)-sig(jo))*sdifb - (psum+pdif)*tempb1&
&             + (sig(jq)-sig(jo))*ssumb
            dsiob = dsiob + (pdif-psum)*tempb1
            pdifb = pdifb - (dsip-dsio)*tempb1
            dspb = -(dsipb/dsp**2)
            CALL POPREAL8(dsp)
            IF ((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2 .EQ. 0.0_8) THEN
              tempb1 = 0.0_8
            ELSE
              tempb1 = dspb/(2.0*SQRT((x(jq)-x(jo))**2+(y(jq)-y(jo))**2)&
&               )
            END IF
            tempb0 = 2*(x(jq)-x(jo))*tempb1
            tempb = 2*(y(jq)-y(jo))*tempb1
            yb0(jq) = yb0(jq) + tempb
            yb0(jo) = yb0(jo) - tempb
            xb0(jq) = xb0(jq) + tempb0
            xb0(jo) = xb0(jo) - tempb0
            x0 = 0.5*(x1+x2)
            dxinv = 1.0/(x0-x2)
            CALL POPREAL8(pdyy)
            tempb1 = dxinv*pdyyb
            psyyb = yyi*psnib + (x0+x2)*tempb1
            x0b = psyy*tempb1
            x2b = x2b + psyy*tempb1
            tempb0 = 2.0*tempb1
            yyb = yyb + (t0-t2)*tempb0
            t0b = yy*tempb0
            t2b = t2b - yy*tempb0
            tempb1 = dxinv*pdx2b
            psx2b = x2i*psnib + (x0+x2)*tempb1
            x2b = x2b + tempb0 + (psx2-(t2-apan)*2.0)*tempb1
            x0b = x0b + psx2*tempb1 - tempb0
            psumb = psumb + tempb1
            pdifb = pdifb + tempb1
            tempb0 = -(x2*2.0*tempb1)
            t2b = t2b + tempb0
            apanb = apanb - tempb0
            CALL POPREAL8(pdx0)
            tempb1 = dxinv*pdx0b
            psx0b = (x1i+x2i)*0.5*psnib + (x0+x2)*tempb1
            x0b = x0b + (psx0+(t0-apan)*2.0)*tempb1
            x2b = x2b + psx0*tempb1
            psumb = psumb + tempb1
            tempb0 = x0*2.0*tempb1
            pdifb = pdifb - tempb1
            rs0 = x0*x0 + yy*yy
            dxinvb = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*pdyyb + ((x0+&
&             x2)*psx2+psum+pdif-2.0*(x2*(t2-apan)))*pdx2b + ((x0+x2)*&
&             psx0+psum+2.0*(x0*(t0-apan))-pdif)*pdx0b + ((x0+x2)*psum+&
&             rs0*(t0-apan)+(x2-x0)*yy-rs2*(t2-apan))*pdifb
            CALL POPREAL8(pdif)
            tempb1 = dxinv*pdifb
            x0b = x0b + (psum-yy)*tempb1
            x2b = x2b + (psum+yy)*tempb1
            psumb = psumb + (x0+x2)*tempb1
            t0b = t0b + tempb0 + rs0*tempb1 - psx0b - x0*psumb
            apanb = apanb + psx0b - tempb0 - psx2b + (rs2-rs0)*tempb1 + &
&             (x0-x2)*psumb
            t2b = t2b + psx2b + x2*psumb - rs2*tempb1
            rs0b = (t0-apan)*tempb1
            yyb = yyb + (x2-x0)*tempb1 + (g0-g2)*0.5*psumb
            rs2b = rs2b - (t2-apan)*tempb1
            CALL POPREAL8(psum)
            tempb1 = yy*0.5*psumb
            g0b = 0.5*psyyb + tempb1
            g2b = g2b - 0.5*psyyb - tempb1
            tempb1 = -(dxinvb/(x0-x2)**2)
            x2b = x2b + (t2-apan)*psumb - tempb1
            x0b = x0b + tempb1 - (t0-apan)*psumb
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
            psx0 = t0 - apan
            psx1 = -(t1-apan)
            psyy = 0.5*(g1-g0)
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            dsim = 1.0/dsm
            tempb1 = qopi*dqdmb(jp)
            dsiob = dsiob + (sig(jp)-sig(jo))*ssumb - (sig(jp)-sig(jo))*&
&             sdifb + (psni+pdni)*tempb1
            psnib = (dsio+dsim)*tempb1
            dsimb = (psni-pdni)*tempb1
            pdnib = (dsio-dsim)*tempb1
            tempb1 = qopi*dqdmb(jo)
            psnib = psnib - dsio*tempb1
            dsiob = dsiob - (psni+pdni)*tempb1
            pdnib = pdnib - dsio*tempb1
            tempb1 = qopi*dqdmb(jm)
            pdnib = pdnib + dsim*tempb1
            dsimb = dsimb + (pdni-psni)*tempb1
            psnib = psnib - dsim*tempb1
            ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
            sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
            tempb1 = qopi*psi_nib
            psnib = psnib + ssum*tempb1
            ssumb = psni*tempb1
            pdnib = pdnib + sdif*tempb1
            sdifb = pdni*tempb1
            pdx1b = x1i*pdnib
            pdx0b = (x1i+x2i)*0.5*pdnib
            tempb1 = pdx0*0.5*pdnib
            x1ib = x1ib + pdx1*pdnib + tempb1
            pdyyb = yyi*pdnib
            yyib = yyib + pdyy*pdnib + psyy*psnib
            x2ib = x2ib + tempb1
            tempb1 = psx0*0.5*psnib
            x1ib = x1ib + psx1*psnib + tempb1
            x2ib = x2ib + tempb1
            tempb1 = qopi*dzdmb(jp)
            psumb = (dsio+dsim)*tempb1
            dsiob = dsiob + (psum+pdif)*tempb1
            dsimb = dsimb + (psum-pdif)*tempb1
            pdifb = (dsio-dsim)*tempb1
            tempb1 = qopi*dzdmb(jo)
            psumb = psumb - dsio*tempb1
            dsiob = dsiob + (sig(jp)-sig(jo))*sdifb - (psum+pdif)*tempb1&
&             + (sig(jp)-sig(jo))*ssumb
            pdifb = pdifb - dsio*tempb1
            tempb1 = qopi*dzdmb(jm)
            pdifb = pdifb + dsim*tempb1
            dsimb = dsimb + (pdif-psum)*tempb1 + (sig(jp)-sig(jm))*ssumb&
&             - (sig(jp)-sig(jm))*sdifb
            psumb = psumb - dsim*tempb1
            dsmb = -(dsimb/dsm**2)
            CALL POPREAL8(dsm)
            IF ((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2 .EQ. 0.0_8) THEN
              tempb1 = 0.0_8
            ELSE
              tempb1 = dsmb/(2.0*SQRT((x(jp)-x(jm))**2+(y(jp)-y(jm))**2)&
&               )
            END IF
            tempb0 = 2*(x(jp)-x(jm))*tempb1
            tempb = 2*(y(jp)-y(jm))*tempb1
            yb0(jp) = yb0(jp) + tempb
            yb0(jm) = yb0(jm) - tempb
            xb0(jp) = xb0(jp) + tempb0
            xb0(jm) = xb0(jm) - tempb0
            dxinv = 1.0/(x1-x0)
            tempb1 = dxinv*pdyyb
            psyyb = yyi*psnib + (x1+x0)*tempb1
            x1b = x1b + psyy*tempb1
            x0b = x0b + psyy*tempb1
            tempb0 = 2.0*tempb1
            yyb = yyb + (t1-t0)*tempb0
            t1b = t1b + yy*tempb0
            t0b = t0b - yy*tempb0
            CALL POPREAL8(pdx0)
            tempb1 = dxinv*pdx0b
            psx0b = (x1i+x2i)*0.5*psnib + (x1+x0)*tempb1
            x0b = x0b + tempb0 + (psx0-(t0-apan)*2.0)*tempb1
            x1b = x1b + psx0*tempb1 - tempb0
            psumb = psumb + tempb1
            pdifb = pdifb + tempb1
            tempb0 = -(x0*2.0*tempb1)
            t0b = t0b + tempb0
            apanb = apanb - tempb0
            tempb1 = dxinv*pdx1b
            psx1b = x1i*psnib + (x1+x0)*tempb1
            x1b = x1b + (psx1+(t1-apan)*2.0)*tempb1
            x0b = x0b + psx1*tempb1
            psumb = psumb + tempb1
            tempb0 = x1*2.0*tempb1
            pdifb = pdifb - tempb1
            dxinvb = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*pdyyb + ((x1+&
&             x0)*psx0+psum+pdif-2.0*(x0*(t0-apan)))*pdx0b + ((x1+x0)*&
&             psx1+psum+2.0*(x1*(t1-apan))-pdif)*pdx1b + ((x1+x0)*psum+&
&             rs1*(t1-apan)+(x0-x1)*yy-rs0*(t0-apan))*pdifb
            CALL POPREAL8(pdif)
            tempb1 = dxinv*pdifb
            x1b = x1b + (psum-yy)*tempb1
            x0b = x0b + (psum+yy)*tempb1
            psumb = psumb + (x1+x0)*tempb1
            t1b = t1b + tempb0 + rs1*tempb1 - psx1b - x1*psumb
            apanb = apanb + psx1b - tempb0 - psx0b + (rs0-rs1)*tempb1 + &
&             (x1-x0)*psumb
            t0b = t0b + psx0b + x0*psumb - rs0*tempb1
            rs1b = rs1b + (t1-apan)*tempb1
            yyb = yyb + (x0-x1)*tempb1
            rs0b = rs0b - (t0-apan)*tempb1
            CALL POPREAL8(psum)
            tempb1 = yy*0.5*psumb
            g1b = g1b + 0.5*psyyb + tempb1
            g0b = g0b - 0.5*psyyb - tempb1
            tempb1 = -(dxinvb/(x1-x0)**2)
            rs0b = rs0b + g0b/rs0
            x0b = x0b + (t0-apan)*psumb + sgn**2*yy*t0b/((sgn*x0)**2+(&
&             sgn*yy)**2) - tempb1 + 2*x0*rs0b
            x1b = x1b + tempb1 - (t1-apan)*psumb + 0.5*x0b
            yyb = yyb + (g1-g0)*0.5*psumb + 2*yy*rs0b - sgn**2*x0*t0b/((&
&             sgn*x0)**2+(sgn*yy)**2)
            CALL POPREAL8(t0)
            CALL POPREAL8(g0)
            x2b = x2b + 0.5*x0b
          ELSE
            dsiob = 0.0_8
          END IF
        END IF
      END IF
      CALL POPREAL8(yyi)
      sxb = nyi*yyib + nxi*x2ib + nxi*x1ib
      syb = nyi*x2ib - nxi*yyib + nyi*x1ib
      CALL POPREAL8(x2i)
      CALL POPREAL8(x1i)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(t2)
        x2b = x2b + sgn**2*yy*t2b/((sgn*x2)**2+(sgn*yy)**2)
        yyb = yyb - sgn**2*x2*t2b/((sgn*x2)**2+(sgn*yy)**2)
        CALL POPREAL8(g2)
        rs2b = rs2b + g2b/rs2
      ELSE
        CALL POPREAL8(t2)
        CALL POPREAL8(g2)
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(t1)
        x1b = x1b + sgn**2*yy*t1b/((sgn*x1)**2+(sgn*yy)**2)
        yyb = yyb - sgn**2*x1*t1b/((sgn*x1)**2+(sgn*yy)**2)
        CALL POPREAL8(g1)
        rs1b = rs1b + g1b/rs1
      ELSE
        CALL POPREAL8(t1)
        CALL POPREAL8(g1)
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(sgn)
      ELSE
        CALL POPREAL8(sgn)
      END IF
      rx2b = 2*rx2*rs2b + sx*x2b
      ry2b = 2*ry2*rs2b + sy*x2b
      rx1b = 2*rx1*rs1b + sx*x1b - sy*yyb
      ry1b = 2*ry1*rs1b + sx*yyb + sy*x1b
      CALL POPREAL8(yy)
      sxb = sxb + ry1*yyb + rx2*x2b + rx1*x1b
      syb = syb + ry2*x2b - rx1*yyb + ry1*x1b
      CALL POPREAL8(x2)
      CALL POPREAL8(x1)
      CALL POPREAL8(sy)
      yb0(jp) = yb0(jp) + dsio*syb
      yb0(jo) = yb0(jo) - dsio*syb
      dsiob = dsiob + (y(jp)-y(jo))*syb + (x(jp)-x(jo))*sxb
      CALL POPREAL8(sx)
      xb0(jp) = xb0(jp) + dsio*sxb
      xb0(jo) = xb0(jo) - dsio*sxb
      CALL POPREAL8(ry2)
      yib = yib + ry2b + ry1b
      yb0(jp) = yb0(jp) - ry2b
      CALL POPREAL8(rx2)
      xib = xib + rx2b + rx1b
      xb0(jp) = xb0(jp) - rx2b
      CALL POPREAL8(ry1)
      yb0(jo) = yb0(jo) - ry1b
      CALL POPREAL8(rx1)
      xb0(jo) = xb0(jo) - rx1b
      CALL POPREAL8(apan)
      apanelb(jo) = apanelb(jo) + apanb
      CALL POPREAL8(dsio)
      dsob = -(dsiob/dso**2)
      yyib = 0.0_8
      g1b = 0.0_8
      g2b = 0.0_8
      x1ib = 0.0_8
      t1b = 0.0_8
      t2b = 0.0_8
      x2ib = 0.0_8
      apanb = 0.0_8
 130  CALL POPREAL8(dso)
      IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .EQ. 0.0_8) THEN
        tempb = 0.0_8
      ELSE
        tempb = dsob/(2.0*SQRT((x(jo)-x(jp))**2+(y(jo)-y(jp))**2))
      END IF
      tempb0 = 2*(x(jo)-x(jp))*tempb
      tempb1 = 2*(y(jo)-y(jp))*tempb
      yb0(jo) = yb0(jo) + tempb1
      yb0(jp) = yb0(jp) - tempb1
      xb0(jo) = xb0(jo) + tempb0
      xb0(jp) = xb0(jp) - tempb0
      CALL POPCONTROL2B(branch)
 140  CALL POPINTEGER4(jq)
      CALL POPINTEGER4(jm)
      CALL POPINTEGER4(jp)
 150  CALL POPINTEGER4(jo)
    END DO
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      asteb = asteb + sdsb/dste
      dsteb = dsteb - aste*sdsb/dste**2 - ante*scsb/dste**2
      anteb = anteb + scsb/dste
    END IF
    CALL POPREAL8(psi_ni)
    DO jo=n,1,-1
      dqdmb(jo) = 0.0_8
      dzdmb(jo) = 0.0_8
    END DO
    DO jo=n,1,-1
      dqdgb(jo) = 0.0_8
    END DO
    CALL POPREAL8(sina)
    alfab = alfab + COS(alfa)*sinab - SIN(alfa)*cosab
    CALL POPREAL8(cosa)
  END SUBROUTINE PSILIN_XW_BWD

!*** XFOILAD: copy of PSILIN without the QTAN1/QTAN2 (GAMU) part, used by
!    XYWAKE. With the shared PSILIN, Tapenade judged GAMU inactive inside
!    XYWAKE and reset its derivative, losing the d(QINVU wake)/d(geometry)
!    contribution computed later by QWCALC.
  SUBROUTINE PSILIN_XW(i, xi, yi, nxi, nyi, psi, psi_ni, geolin, siglin)
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    LOGICAL :: geolin, siglin
    INTEGER :: i
    REAL :: nxi, nyi, psi, psi_ni, xi, yi
! intent (in) Geolin, I, Nxi, Nyi, Siglin, Xi, Yi
! intent (inout) Psi, Psi_ni
!
! Local variables
!
    REAL :: apan, dsim, dsio, dsip, dsm, dso, dsp, dxinv, g0, g1, g2, &
&   gamte1, gamte2, gdif, gdif1, gdif2, gsum, gsum1, gsum2, nxo, nxp, &
&   nyo, nyp, pdif, pdni, pdx0, pdx1, pdx2, pdyy, pgam, pgamni, pgamx1, &
&   pgamx2, pgamyy, psid, psig, psigni, psigx1, psigx2, psigyy, psis, &
&   psni, psum, psx0, psx1, psx2, psyy, qtanm, rs0, rs1, rs2, rx1, rx2, &
&   ry1, ry2, scs, sdif, sds, seps, sgn, sigte1, sigte2, ssum, sx, sy, &
&   t0, t1, t2, x0, x1, x1i, x1o, x1p, x2, x2i, x2o, x2p, xjo
    REAL :: xjp, yjo
    INTEGER :: io, jm, jo, jp, jq
    REAL :: yjp, yy, yyi, yyo, yyp
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC SQRT
    INTRINSIC EPSILON
    INTRINSIC SIGN
    INTRINSIC LOG
    INTRINSIC ATAN2
    REAL :: result1
    REAL :: result2
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------------------------------------
!     Calculates current streamfunction Psi at panel node or wake node
!     I due to freestream and all bound vorticity Gam on the airfoil.
!     Sensitivities of Psi with respect to alpha (Z_ALFA) and inverse
!     Qspec DOFs (Z_QDOF0,Z_QDOF1) which influence Gam in inverse cases.
!     Also calculates the sensitivity vector dPsi/dGam (DZDG).
!
!     If SIGLIN=True, then Psi includes the effects of the viscous
!     source distribution Sig and the sensitivity vector dPsi/dSig
!     (DZDM) is calculated.
!
!     If GEOLIN=True, then the geometric sensitivity vector dPsi/dn
!     is calculated, where n is the normal motion of the jth node.
!
!          Airfoil:  1   < I < N
!          Wake:     N+1 < I < N+NW
!-----------------------------------------------------------------------
!
!---- distance tolerance for determining if two points are the same
    seps = (s(n)-s(1))*1.0e-5
!
    io = i
!
    cosa = COS(alfa)
    sina = SIN(alfa)
!
    DO jo=1,n
      dzdg(jo) = 0.0
      dzdn(jo) = 0.0
      dqdg(jo) = 0.0
    END DO
!
    DO jo=1,n
      dzdm(jo) = 0.0
      dqdm(jo) = 0.0
    END DO
!
    z_qinf = 0.
    z_alfa = 0.
    z_qdof0 = 0.
    z_qdof1 = 0.
    z_qdof2 = 0.
    z_qdof3 = 0.
!
    psi = 0.
    psi_ni = 0.
!
    qtanm = 0.
!
    IF (sharp) THEN
      scs = 1.0
      sds = 0.0
    ELSE
      scs = ante/dste
      sds = aste/dste
    END IF
!
    DO jo=1,n
      jp = jo + 1
!
      jm = jo - 1
      jq = jp + 1
!
      IF (jo .EQ. 1) THEN
        jm = jo
      ELSE IF (jo .EQ. n - 1) THEN
        jq = jp
      ELSE IF (jo .EQ. n) THEN
        jp = 1
        IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO 100
      END IF
!
      dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then 
      result1 = EPSILON(0.)
      result2 = EPSILON(0.)
      IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) THEN
!
        dsio = 1.0/dso
!
        apan = apanel(jo)
!
        rx1 = xi - x(jo)
        ry1 = yi - y(jo)
        rx2 = xi - x(jp)
        ry2 = yi - y(jp)
!
        sx = (x(jp)-x(jo))*dsio
        sy = (y(jp)-y(jo))*dsio
!
        x1 = sx*rx1 + sy*ry1
        x2 = sx*rx2 + sy*ry2
        yy = sx*ry1 - sy*rx1
!
        rs1 = rx1*rx1 + ry1*ry1
        rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
        IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
          sgn = 1.0
        ELSE
!------- make sure arctan falls between  -/+  Pi/2
          sgn = SIGN(1.0, yy)
        END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
        IF (io .NE. jo .AND. rs1 .GT. 0.0) THEN
          g1 = LOG(rs1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
        ELSE
          g1 = 0.0
          t1 = 0.0
        END IF
!
        IF (io .NE. jp .AND. rs2 .GT. 0.0) THEN
          g2 = LOG(rs2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
        ELSE
          g2 = 0.0
          t2 = 0.0
        END IF
!
        x1i = sx*nxi + sy*nyi
        x2i = sx*nxi + sy*nyi
        yyi = sx*nyi - sy*nxi
!
        IF (geolin) THEN
          nxo = nx(jo)
          nyo = ny(jo)
          nxp = nx(jp)
          nyp = ny(jp)
!
          x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy*&
&           nyo)
          x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
          x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
          x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*nyp)
          yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*nxo)
          yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
        END IF
!
        IF (jo .EQ. n) THEN
          GOTO 110
        ELSE
!
          IF (siglin) THEN
!
!------- set up midpoint quantities
            x0 = 0.5*(x1+x2)
            rs0 = x0*x0 + yy*yy
            g0 = LOG(rs0)
            t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
            dxinv = 1.0/(x1-x0)
            psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
            pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*yy)&
&             *dxinv
!
            psx1 = -(t1-apan)
            psx0 = t0 - apan
            psyy = 0.5*(g1-g0)
!
            pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
            pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
            pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
            dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
            dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
            ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
            sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
            psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
            dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
            dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-dsim&
&             ))
!
!------- dPsi/dni
            psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
            pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
            qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
            dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
            dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-dsim&
&             ))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
            dxinv = 1.0/(x0-x2)
            psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
            pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*yy)&
&             *dxinv
!
            psx0 = -(t0-apan)
            psx2 = t2 - apan
            psyy = 0.5*(g0-g2)
!
            pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
            pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
            pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
            dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
            dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
            ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
            sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
            psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
            dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip-&
&             dsio))
            dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
            dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
            psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
            pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
            psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
            qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
            dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip-&
&             dsio))
            dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
            dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
          END IF
!
!------ calculate vortex panel contribution to Psi
          dxinv = 1.0/(x1-x2)
          psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
          psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
          psx1 = 0.5*g1
          psx2 = -(.5*g2)
          psyy = t1 - t2
!
          pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
          pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
          pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
!
          gsum = gam(jp) + gam(jo)
          gdif = gam(jp) - gam(jo)
!
          psi = psi + qopi*(psis*gsum+psid*gdif)
!
!------ dPsi/dGam
          dzdg(jo) = dzdg(jo) + qopi*(psis-psid)
          dzdg(jp) = dzdg(jp) + qopi*(psis+psid)
!
!------ dPsi/dni
          psni = psx1*x1i + psx2*x2i + psyy*yyi
          pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
          psi_ni = psi_ni + qopi*(gsum*psni+gdif*pdni)
!
!
          dqdg(jo) = dqdg(jo) + qopi*(psni-pdni)
          dqdg(jp) = dqdg(jp) + qopi*(psni+pdni)
!
          IF (geolin) THEN
!
!------- dPsi/dn
            dzdn(jo) = dzdn(jo) + qopi*gsum*(psx1*x1o+psx2*x2o+psyy*yyo)&
&             + qopi*gdif*(pdx1*x1o+pdx2*x2o+pdyy*yyo)
            dzdn(jp) = dzdn(jp) + qopi*gsum*(psx1*x1p+psx2*x2p+psyy*yyp)&
&             + qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
            z_qdof0 = z_qdof0 + qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&             qf0(jp))
            z_qdof1 = z_qdof1 + qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&             qf1(jp))
            z_qdof2 = z_qdof2 + qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&             qf2(jp))
            z_qdof3 = z_qdof3 + qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&             qf3(jp))
          END IF
        END IF
      END IF
    END DO
!
!
!
 110 psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
    pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
    psigx1 = -(t1-apan)
    psigx2 = t2 - apan
    psigyy = 0.5*(g1-g2)
    pgamx1 = 0.5*g1
    pgamx2 = -(.5*g2)
    pgamyy = t1 - t2
!
    psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
    pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
!
    sigte = 0.5*scs*(gam(jp)-gam(jo))
    gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
    psi = psi + hopi*(psig*sigte+pgam*gamte)
!
!---- dPsi/dGam
    dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
    dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
    dzdg(jo) = dzdg(jo) + hopi*pgam*sds*0.5
    dzdg(jp) = dzdg(jp) - hopi*pgam*sds*0.5
!
!---- dPsi/dni
    psi_ni = psi_ni + hopi*(psigni*sigte+pgamni*gamte)
!
!
    dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs-pgamni*0.5*sds)
    dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs-pgamni*0.5*sds)
!
    IF (geolin) THEN
!
!----- dPsi/dn
      dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&       sigte + hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
      dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&       sigte + hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
      z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs - hopi*&
&       pgam*0.5*(qf0(jp)-qf0(jo))*sds
      z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs - hopi*&
&       pgam*0.5*(qf1(jp)-qf1(jo))*sds
      z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs - hopi*&
&       pgam*0.5*(qf2(jp)-qf2(jo))*sds
      z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs - hopi*&
&       pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
    END IF
!
!
!**** Freestream terms
 100 psi = psi + qinf*(cosa*yi-sina*xi)
!
!---- dPsi/dn
    psi_ni = psi_ni + qinf*(cosa*nyi-sina*nxi)
!
!
!---- dPsi/dQinf
    z_qinf = z_qinf + (cosa*yi-sina*xi)
!
!---- dPsi/dalfa
    z_alfa = z_alfa - qinf*(sina*yi+cosa*xi)
!
    IF (.NOT.limage) THEN
      RETURN
    ELSE
!
!
!
      DO jo=1,n
        jp = jo + 1
!
        jm = jo - 1
        jq = jp + 1
!
        IF (jo .EQ. 1) THEN
          jm = jo
        ELSE IF (jo .EQ. n - 1) THEN
          jq = jp
        ELSE IF (jo .EQ. n) THEN
          jp = 1
          IF ((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2 .LT. seps**2) GOTO &
&            99999
        END IF
!
        dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
!
!------ skip null panel
! if (dso/=0.0) then
        result1 = EPSILON(0.)
        result2 = EPSILON(0.)
        IF (.NOT.(dso .GE. 0. - result1 .AND. dso .LE. 0. + result2)) &
&       THEN
!
          dsio = 1.0/dso
!
!cc     APAN = APANEL(JO)
          apan = pi - apanel(jo) + 2.0*alfa
!
          xjo = x(jo) + 2.0*(yimage+y(jo))*sina
          yjo = y(jo) - 2.0*(yimage+y(jo))*cosa
          xjp = x(jp) + 2.0*(yimage+y(jp))*sina
          yjp = y(jp) - 2.0*(yimage+y(jp))*cosa
!
          rx1 = xi - xjo
          ry1 = yi - yjo
          rx2 = xi - xjp
          ry2 = yi - yjp
!
          sx = (xjp-xjo)*dsio
          sy = (yjp-yjo)*dsio
!
          x1 = sx*rx1 + sy*ry1
          x2 = sx*rx2 + sy*ry2
          yy = sx*ry1 - sy*rx1
!
          rs1 = rx1*rx1 + ry1*ry1
          rs2 = rx2*rx2 + ry2*ry2
!
!------ set reflection flag SGN to avoid branch problems with arctan
          IF (io .GE. 1 .AND. io .LE. n) THEN
!------- no problem on airfoil surface
            sgn = 1.0
          ELSE
!------- make sure arctan falls between  -/+  Pi/2
            sgn = SIGN(1.0, yy)
          END IF
!
!------ set log(r^2) and arctan(x/y), correcting for reflection if any
          g1 = LOG(rs1)
          t1 = ATAN2(sgn*x1, sgn*yy) + (0.5-0.5*sgn)*pi
!
          g2 = LOG(rs2)
          t2 = ATAN2(sgn*x2, sgn*yy) + (0.5-0.5*sgn)*pi
!
          x1i = sx*nxi + sy*nyi
          x2i = sx*nxi + sy*nyi
          yyi = sx*nyi - sy*nxi
!
          IF (geolin) THEN
            nxo = nx(jo)
            nyo = ny(jo)
            nxp = nx(jp)
            nyp = ny(jp)
!
            x1o = -(((rx1-x1*sx)*nxo+(ry1-x1*sy)*nyo)*dsio) - (sx*nxo+sy&
&             *nyo)
            x1p = ((rx1-x1*sx)*nxp+(ry1-x1*sy)*nyp)*dsio
            x2o = -(((rx2-x2*sx)*nxo+(ry2-x2*sy)*nyo)*dsio)
            x2p = ((rx2-x2*sx)*nxp+(ry2-x2*sy)*nyp)*dsio - (sx*nxp+sy*&
&             nyp)
            yyo = ((rx1+x1*sy)*nyo-(ry1-x1*sx)*nxo)*dsio - (sx*nyo-sy*&
&             nxo)
            yyp = -(((rx1-x1*sy)*nyp-(ry1+x1*sx)*nxp)*dsio)
          END IF
!
          IF (jo .EQ. n) THEN
            GOTO 120
          ELSE
!
            IF (siglin) THEN
!
!------- set up midpoint quantities
              x0 = 0.5*(x1+x2)
              rs0 = x0*x0 + yy*yy
              g0 = LOG(rs0)
              t0 = ATAN2(sgn*x0, sgn*yy) + (0.5-0.5*sgn)*pi
!
!------- calculate source contribution to Psi  for  1-0  half-panel
              dxinv = 1.0/(x1-x0)
              psum = x0*(t0-apan) - x1*(t1-apan) + 0.5*yy*(g1-g0)
              pdif = ((x1+x0)*psum+rs1*(t1-apan)-rs0*(t0-apan)+(x0-x1)*&
&               yy)*dxinv
!
              psx1 = -(t1-apan)
              psx0 = t0 - apan
              psyy = 0.5*(g1-g0)
!
              pdx1 = ((x1+x0)*psx1+psum+2.0*x1*(t1-apan)-pdif)*dxinv
              pdx0 = ((x1+x0)*psx0+psum-2.0*x0*(t0-apan)+pdif)*dxinv
              pdyy = ((x1+x0)*psyy+2.0*(x0-x1+yy*(t1-t0)))*dxinv
!
              dsm = SQRT((x(jp)-x(jm))**2 + (y(jp)-y(jm))**2)
              dsim = 1.0/dsm
!
!CC      SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC      SIG1 = (SIG(JP) - SIG(JM))*DSIM
!CC      SSUM = SIG0 + SIG1
!CC      SDIF = SIG0 - SIG1
!
              ssum = (sig(jp)-sig(jo))*dsio + (sig(jp)-sig(jm))*dsim
              sdif = (sig(jp)-sig(jo))*dsio - (sig(jp)-sig(jm))*dsim
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdm(jm) = dzdm(jm) + qopi*(-(psum*dsim)+pdif*dsim)
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*dsio)-pdif*dsio)
              dzdm(jp) = dzdm(jp) + qopi*(psum*(dsio+dsim)+pdif*(dsio-&
&               dsim))
!
!------- dPsi/dni
              psni = psx1*x1i + psx0*(x1i+x2i)*0.5 + psyy*yyi
              pdni = pdx1*x1i + pdx0*(x1i+x2i)*0.5 + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdm(jm) = dqdm(jm) + qopi*(-(psni*dsim)+pdni*dsim)
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*dsio)-pdni*dsio)
              dqdm(jp) = dqdm(jp) + qopi*(psni*(dsio+dsim)+pdni*(dsio-&
&               dsim))
!
!
!------- calculate source contribution to Psi  for  0-2  half-panel
              dxinv = 1.0/(x0-x2)
              psum = x2*(t2-apan) - x0*(t0-apan) + 0.5*yy*(g0-g2)
              pdif = ((x0+x2)*psum+rs0*(t0-apan)-rs2*(t2-apan)+(x2-x0)*&
&               yy)*dxinv
!
              psx0 = -(t0-apan)
              psx2 = t2 - apan
              psyy = 0.5*(g0-g2)
!
              pdx0 = ((x0+x2)*psx0+psum+2.0*x0*(t0-apan)-pdif)*dxinv
              pdx2 = ((x0+x2)*psx2+psum-2.0*x2*(t2-apan)+pdif)*dxinv
              pdyy = ((x0+x2)*psyy+2.0*(x2-x0+yy*(t0-t2)))*dxinv
!
              dsp = SQRT((x(jq)-x(jo))**2 + (y(jq)-y(jo))**2)
              dsip = 1.0/dsp
!
!CC         SIG2 = (SIG(JQ) - SIG(JO))*DSIP
!CC         SIG0 = (SIG(JP) - SIG(JO))*DSIO
!CC         SSUM = SIG2 + SIG0
!CC         SDIF = SIG2 - SIG0
!
              ssum = (sig(jq)-sig(jo))*dsip + (sig(jp)-sig(jo))*dsio
              sdif = (sig(jq)-sig(jo))*dsip - (sig(jp)-sig(jo))*dsio
!
              psi = psi + qopi*(psum*ssum+pdif*sdif)
!
!------- dPsi/dm
              dzdm(jo) = dzdm(jo) + qopi*(-(psum*(dsip+dsio))-pdif*(dsip&
&               -dsio))
              dzdm(jp) = dzdm(jp) + qopi*(psum*dsio-pdif*dsio)
              dzdm(jq) = dzdm(jq) + qopi*(psum*dsip+pdif*dsip)
!
!------- dPsi/dni
              psni = psx0*(x1i+x2i)*0.5 + psx2*x2i + psyy*yyi
              pdni = pdx0*(x1i+x2i)*0.5 + pdx2*x2i + pdyy*yyi
              psi_ni = psi_ni + qopi*(psni*ssum+pdni*sdif)
!
              qtanm = qtanm + qopi*(psni*ssum+pdni*sdif)
!
              dqdm(jo) = dqdm(jo) + qopi*(-(psni*(dsip+dsio))-pdni*(dsip&
&               -dsio))
              dqdm(jp) = dqdm(jp) + qopi*(psni*dsio-pdni*dsio)
              dqdm(jq) = dqdm(jq) + qopi*(psni*dsip+pdni*dsip)
!
            END IF
!
!------ calculate vortex panel contribution to Psi
            dxinv = 1.0/(x1-x2)
            psis = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
            psid = ((x1+x2)*psis+0.5*(rs2*g2-rs1*g1+x1*x1-x2*x2))*dxinv
!
            psx1 = 0.5*g1
            psx2 = -(.5*g2)
            psyy = t1 - t2
!
            pdx1 = ((x1+x2)*psx1+psis-x1*g1-psid)*dxinv
            pdx2 = ((x1+x2)*psx2+psis+x2*g2+psid)*dxinv
            pdyy = ((x1+x2)*psyy-yy*(g1-g2))*dxinv
!
!
            gsum = gam(jp) + gam(jo)
            gdif = gam(jp) - gam(jo)
!
            psi = psi - qopi*(psis*gsum+psid*gdif)
!
!------ dPsi/dGam
            dzdg(jo) = dzdg(jo) - qopi*(psis-psid)
            dzdg(jp) = dzdg(jp) - qopi*(psis+psid)
!
!------ dPsi/dni
            psni = psx1*x1i + psx2*x2i + psyy*yyi
            pdni = pdx1*x1i + pdx2*x2i + pdyy*yyi
            psi_ni = psi_ni - qopi*(gsum*psni+gdif*pdni)
!
!
            dqdg(jo) = dqdg(jo) - qopi*(psni-pdni)
            dqdg(jp) = dqdg(jp) - qopi*(psni+pdni)
!
            IF (geolin) THEN
!
!------- dPsi/dn
              dzdn(jo) = dzdn(jo) - qopi*gsum*(psx1*x1o+psx2*x2o+psyy*&
&               yyo) - qopi*gdif*(pdx1*x1o+pdx2*x2o+pdyy*yyo)
              dzdn(jp) = dzdn(jp) - qopi*gsum*(psx1*x1p+psx2*x2p+psyy*&
&               yyp) - qopi*gdif*(pdx1*x1p+pdx2*x2p+pdyy*yyp)
!------- dPsi/dP
              z_qdof0 = z_qdof0 - qopi*((psis-psid)*qf0(jo)+(psis+psid)*&
&               qf0(jp))
              z_qdof1 = z_qdof1 - qopi*((psis-psid)*qf1(jo)+(psis+psid)*&
&               qf1(jp))
              z_qdof2 = z_qdof2 - qopi*((psis-psid)*qf2(jo)+(psis+psid)*&
&               qf2(jp))
              z_qdof3 = z_qdof3 - qopi*((psis-psid)*qf3(jo)+(psis+psid)*&
&               qf3(jp))
            END IF
          END IF
        END IF
      END DO
!
!
!
 120  psig = 0.5*yy*(g1-g2) + x2*(t2-apan) - x1*(t1-apan)
      pgam = 0.5*x1*g1 - 0.5*x2*g2 + x2 - x1 + yy*(t1-t2)
!
      psigx1 = -(t1-apan)
      psigx2 = t2 - apan
      psigyy = 0.5*(g1-g2)
      pgamx1 = 0.5*g1
      pgamx2 = -(.5*g2)
      pgamyy = t1 - t2
!
      psigni = psigx1*x1i + psigx2*x2i + psigyy*yyi
      pgamni = pgamx1*x1i + pgamx2*x2i + pgamyy*yyi
!
!---- TE panel source and vortex strengths
!
      sigte = 0.5*scs*(gam(jp)-gam(jo))
      gamte = -(.5*sds*(gam(jp)-gam(jo)))
!
!---- TE panel contribution to Psi
      psi = psi + hopi*(psig*sigte-pgam*gamte)
!
!---- dPsi/dGam
      dzdg(jo) = dzdg(jo) - hopi*psig*scs*0.5
      dzdg(jp) = dzdg(jp) + hopi*psig*scs*0.5
!
      dzdg(jo) = dzdg(jo) - hopi*pgam*sds*0.5
      dzdg(jp) = dzdg(jp) + hopi*pgam*sds*0.5
!
!---- dPsi/dni
      psi_ni = psi_ni + hopi*(psigni*sigte-pgamni*gamte)
!
!
      dqdg(jo) = dqdg(jo) - hopi*(psigni*0.5*scs+pgamni*0.5*sds)
      dqdg(jp) = dqdg(jp) + hopi*(psigni*0.5*scs+pgamni*0.5*sds)
!
      IF (geolin) THEN
!
!----- dPsi/dn
        dzdn(jo) = dzdn(jo) + hopi*(psigx1*x1o+psigx2*x2o+psigyy*yyo)*&
&         sigte - hopi*(pgamx1*x1o+pgamx2*x2o+pgamyy*yyo)*gamte
        dzdn(jp) = dzdn(jp) + hopi*(psigx1*x1p+psigx2*x2p+psigyy*yyp)*&
&         sigte - hopi*(pgamx1*x1p+pgamx2*x2p+pgamyy*yyp)*gamte
!
!----- dPsi/dP
        z_qdof0 = z_qdof0 + hopi*psig*0.5*(qf0(jp)-qf0(jo))*scs + hopi*&
&         pgam*0.5*(qf0(jp)-qf0(jo))*sds
        z_qdof1 = z_qdof1 + hopi*psig*0.5*(qf1(jp)-qf1(jo))*scs + hopi*&
&         pgam*0.5*(qf1(jp)-qf1(jo))*sds
        z_qdof2 = z_qdof2 + hopi*psig*0.5*(qf2(jp)-qf2(jo))*scs + hopi*&
&         pgam*0.5*(qf2(jp)-qf2(jo))*sds
        z_qdof3 = z_qdof3 + hopi*psig*0.5*(qf3(jp)-qf3(jo))*scs + hopi*&
&         pgam*0.5*(qf3(jp)-qf3(jo))*sds
!
      END IF
    END IF
99999 CONTINUE
  END SUBROUTINE PSILIN_XW

