!
!*** End of declarations rewritten by SPAG
!
!--------------------------------------------------------------------
!     Calculates current streamfunction Psi and tangential velocity
!     Qtan at panel node or wake node I due to freestream and wake
!     sources Sig.  Also calculates sensitivity vectors dPsi/dSig
!     (DZDM) and dQtan/dSig (DQDM).
!
!          Airfoil:  1   < I < N
!          Wake:     N+1 < I < N+NW
!--------------------------------------------------------------------
!
    io = i
!
!
    DO jo=n+1,n+nw
      dzdm(jo) = 0.0
      dqdm(jo) = 0.0
    END DO
!
    DO jo=n+1,n+nw-1
!
      jp = jo + 1
!
      CALL PUSHINTEGER4(jm)
      jm = jo - 1
      CALL PUSHINTEGER4(jq)
      jq = jp + 1
      IF (jo .EQ. n + 1) THEN
        CALL PUSHCONTROL1B(0)
        jm = jo
      ELSE IF (jo .EQ. n + nw - 1) THEN
        CALL PUSHCONTROL1B(1)
        jq = jp
      ELSE
        CALL PUSHCONTROL1B(1)
      END IF
!
      CALL PUSHREAL8(dso)
      dso = SQRT((x(jo)-x(jp))**2 + (y(jo)-y(jp))**2)
      dsio = 1.0/dso
!
      apan = apanel(jo)
!
      rx1 = xi - x(jo)
      ry1 = yi - y(jo)
      rx2 = xi - x(jp)
      ry2 = yi - y(jp)
!
      sx = (x(jp)-x(jo))*dsio
      sy = (y(jp)-y(jo))*dsio
