!------ RES1 = PSI( 0) - PSIO
!------ RES2 = PSI(90) - PSIO
      res1 = qinf*y(i)
      res2 = -(qinf*x(i))
!
!------ dRes/dGamma
      DO j=1,n
        CALL PUSHREAL8(aij(i, j))
        aij(i, j) = dzdg(j)
      END DO
!
      DO j=1,n
        CALL PUSHREAL8(bij(i, j))
        bij(i, j) = -dzdm(j)
      END DO
!
!------ dRes/dPsio
      CALL PUSHREAL8(aij(i, n+1))
      aij(i, n+1) = -1.0
!
      CALL PUSHREAL8(gamu(i, 1))
      gamu(i, 1) = -res1
      CALL PUSHREAL8(gamu(i, 2))
      gamu(i, 2) = -res2
    END DO
!
!
!---- set Kutta condition
!-    RES = GAM(1) + GAM(N)
    res = 0.
!
    DO j=1,n+1
      CALL PUSHREAL8(aij(n+1, j))
      aij(n+1, j) = 0.0
    END DO
!
    CALL PUSHREAL8(aij(n+1, 1))
    aij(n+1, 1) = 1.0
    CALL PUSHREAL8(aij(n+1, n))
    aij(n+1, n) = 1.0
!
    CALL PUSHREAL8(gamu(n+1, 1))
    gamu(n+1, 1) = -res
    CALL PUSHREAL8(gamu(n+1, 2))
    gamu(n+1, 2) = -res
!
!---- set up Kutta condition (no direct source influence)
    DO j=1,n
      CALL PUSHREAL8(bij(n+1, j))
      bij(n+1, j) = 0.
    END DO
!
    IF (sharp) THEN
!----- set zero internal velocity in TE corner
!
!----- set TE bisector angle
      ag1 = ATAN2(-yp(1), -xp(1))
      ag2 = ATANC_FWD(yp(n), xp(n), ag1)
      abis = 0.5*(ag1+ag2)
      cbis = COS(abis)
      sbis = SIN(abis)
!
!----- minimum panel length adjacent to TE
      ds1 = SQRT((x(1)-x(2))**2 + (y(1)-y(2))**2)
      ds2 = SQRT((x(n)-x(n-1))**2 + (y(n)-y(n-1))**2)
      IF (ds1 .GT. ds2) THEN
        dsmin = ds2
        CALL PUSHCONTROL1B(0)
      ELSE
        dsmin = ds1
        CALL PUSHCONTROL1B(1)
      END IF
!
!----- control point on bisector just ahead of TE point
      xbis = xte - bwt*dsmin*cbis
      ybis = yte - bwt*dsmin*sbis
!cc       write(*,*) xbis, ybis
!
!----- set velocity component along bisector line
! XFOILAD: normal passed through a variable (an expression argument
! becomes an undeclared temporary in Tapenade's split reverse code)
      nxbis = -sbis
      CALL PSILIN_FWD(0, xbis, ybis, nxbis, cbis, psi, qbis, .false., &
&               .true.)
!
!CC--- RES = DQDGj*Gammaj + DQDMj*Massj + QINF*(COSA*CBIS + SINA*SBIS)
!
!----- dRes/dGamma
      DO j=1,n
        CALL PUSHREAL8(aij(n, j))
        aij(n, j) = dqdg(j)
      END DO
!
!----- -dRes/dMass
      DO j=1,n
        CALL PUSHREAL8(bij(n, j))
        bij(n, j) = -dqdm(j)
      END DO
!
!----- dRes/dPsio
      CALL PUSHREAL8(aij(n, n+1))
      aij(n, n+1) = 0.
!
!----- -dRes/dUinf
      CALL PUSHREAL8(gamu(n, 1))
      gamu(n, 1) = -cbis
!
!----- -dRes/dVinf
      CALL PUSHREAL8(gamu(n, 2))
      gamu(n, 2) = -sbis
!
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!---- LU-factor coefficient matrix AIJ
    arg1 = n + 1
    CALL PUSHINTEGER4ARRAY(aijpiv, 370)
    CALL PUSHREAL8ARRAY(aij, 370**2)
    CALL LUDCMP(iqx, arg1, aij, aijpiv)
!
!---- solve system for the two vorticity distributions
! XFOILAD: columns are copied to a work vector instead of being passed
! by sequence association (BIJ(1,j), GAMU(1,k)): Tapenade otherwise
! pushes/pops IQX*IZX values from that address and overruns the array.
    DO k=1,2
      DO i=1,iqx
        CALL PUSHREAL8(bcol(i))
        bcol(i) = gamu(i, k)
      END DO
      arg1 = n + 1
      CALL BAKSUB_FWD(iqx, arg1, aij, aijpiv, bcol)
      DO i=1,iqx
        CALL PUSHREAL8(gamu(i, k))
        gamu(i, k) = bcol(i)
      END DO
    END DO
!
!---- set inviscid alpha=0,90 surface speeds for this geometry
    DO i=1,n
      CALL PUSHREAL8(qinvu(i, 1))
      qinvu(i, 1) = gamu(i, 1)
      CALL PUSHREAL8(qinvu(i, 2))
      qinvu(i, 2) = gamu(i, 2)
    END DO
    CALL PUSHREAL8(dsmin)
    CALL PUSHREAL8(abis)
    CALL PUSHREAL8(cbis)
    CALL PUSHREAL8(sbis)
    CALL PUSHREAL8ARRAY(bcol, iqx)
  END SUBROUTINE GGCALC_FWD

!  Differentiation of ggcalc in reverse (adjoint) mode, backward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSIL
!IN_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CL
!CALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFil
!e):
!   gradient     of useful results: dqdm qinvu xte x y nx ny xp
!                bij dzdm yp alfa aij yte apanel gamu dqdg
!   with respect to varying inputs: dste xte x y nx ny xp ante
!                aste yp alfa yte apanel
!*==GGCALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE GGCALC_BWD()
    USE M_XSOLVE_DIFF, ONLY : ludcmp, ludcmp_b, baksub, baksub_fwd, baksub_bwd
    USE M_XUTILS_DIFF, ONLY : atanc, atanc_fwd, atanc_bwd
    USE I_XFOIL_DIFF
    IMPLICIT NONE
    REAL(kind=8) :: xadtmpb1, xadtmpb2
!
    REAL :: abis, ag1, ag2, bwt, cbis, ds1, ds2, dsmin, psi, psiinf, &
&   psi_n, qbis, res, res1, res2, sbis, xbis, ybis
    REAL :: abisb, ag1b, ag2b, cbisb, ds1b, ds2b, dsminb, res1b, res2b, &
&   sbisb, xbisb, ybisb
    REAL :: nxbis
    REAL :: nxbisb
    INTEGER :: i, j, k
    REAL, DIMENSION(iqx) :: bcol
    REAL, DIMENSION(iqx) :: bcolb
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC ATAN2
    INTRINSIC SQRT
    INTRINSIC MIN
    INTEGER :: arg1
    REAL :: tempb
    REAL :: tempb0
    REAL :: tempb1
    INTEGER :: branch
    CALL POPREAL8ARRAY(bcol, iqx)
    CALL POPREAL8(sbis)
    CALL POPREAL8(cbis)
    CALL POPREAL8(abis)
    CALL POPREAL8(dsmin)
    DO i=n,1,-1
      CALL POPREAL8(qinvu(i, 2))
      gamub(i, 2) = gamub(i, 2) + qinvub(i, 2)
      qinvub(i, 2) = 0.0_8
      CALL POPREAL8(qinvu(i, 1))
      gamub(i, 1) = gamub(i, 1) + qinvub(i, 1)
      qinvub(i, 1) = 0.0_8
    END DO
    bcolb = 0.0_8
    DO k=2,1,-1
      DO i=iqx,1,-1
        CALL POPREAL8(gamu(i, k))
        bcolb(i) = bcolb(i) + gamub(i, k)
        gamub(i, k) = 0.0_8
      END DO
      arg1 = n + 1
      CALL BAKSUB_BWD(iqx, arg1, aij, aijb, aijpiv, bcol, bcolb)
      DO i=iqx,1,-1
        CALL POPREAL8(bcol(i))
        gamub(i, k) = gamub(i, k) + bcolb(i)
        bcolb(i) = 0.0_8
      END DO
    END DO
    arg1 = n + 1
    CALL POPREAL8ARRAY(aij, 370**2)
    CALL POPINTEGER4ARRAY(aijpiv, 370)
    CALL LUDCMP_B(iqx, arg1, aij, aijb, aijpiv)
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(gamu(n, 2))
      sbisb = -gamub(n, 2)
      gamub(n, 2) = 0.0_8
      CALL POPREAL8(gamu(n, 1))
      cbisb = -gamub(n, 1)
      gamub(n, 1) = 0.0_8
      CALL POPREAL8(aij(n, n+1))
      aijb(n, n+1) = 0.0_8
      DO j=n,1,-1
        CALL POPREAL8(bij(n, j))
        dqdmb(j) = dqdmb(j) - bijb(n, j)
        bijb(n, j) = 0.0_8
      END DO
      DO j=n,1,-1
        CALL POPREAL8(aij(n, j))
        dqdgb(j) = dqdgb(j) + aijb(n, j)
        aijb(n, j) = 0.0_8
      END DO
      bwt = 0.1
      ybis = yte - bwt*dsmin*sbis
      xbis = xte - bwt*dsmin*cbis
      nxbis = -sbis
      xbisb = 0.0_8
      ybisb = 0.0_8
      nxbisb = 0.0_8
      dzdgb = 0.0_8
      asteb = 0.0_8
      anteb = 0.0_8
      dsteb = 0.0_8
      qtan2b = 0.0_8
      qtan1b = 0.0_8
      CALL PSILIN_BWD(0, xbis, xbisb, ybis, ybisb, nxbis, nxbisb, cbis, &
&               cbisb, psi, qbis, .false., .true.)
      sbisb = sbisb - nxbisb - dsmin*bwt*ybisb
      yteb = yteb + ybisb
      dsminb = -(sbis*bwt*ybisb) - cbis*bwt*xbisb
      xteb = xteb + xbisb
      cbisb = cbisb - dsmin*bwt*xbisb
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        ds2b = dsminb
        ds1b = 0.0_8
      ELSE
        ds1b = dsminb
        ds2b = 0.0_8
      END IF
      IF ((x(n)-x(n-1))**2 + (y(n)-y(n-1))**2 .EQ. 0.0_8) THEN
        tempb1 = 0.0_8
      ELSE
        tempb1 = ds2b/(2.0*SQRT((x(n)-x(n-1))**2+(y(n)-y(n-1))**2))
      END IF
      tempb0 = 2*(x(n)-x(n-1))*tempb1
      tempb = 2*(y(n)-y(n-1))*tempb1
      yb0(n) = yb0(n) + tempb
      yb0(n-1) = yb0(n-1) - tempb
      xb0(n) = xb0(n) + tempb0
      xb0(n-1) = xb0(n-1) - tempb0
      IF ((x(1)-x(2))**2 + (y(1)-y(2))**2 .EQ. 0.0_8) THEN
        tempb = 0.0_8
      ELSE
        tempb = ds1b/(2.0*SQRT((x(1)-x(2))**2+(y(1)-y(2))**2))
      END IF
      tempb0 = 2*(x(1)-x(2))*tempb
      tempb1 = 2*(y(1)-y(2))*tempb
      yb0(1) = yb0(1) + tempb1
      yb0(2) = yb0(2) - tempb1
      xb0(1) = xb0(1) + tempb0
      xb0(2) = xb0(2) - tempb0
      abisb = COS(abis)*sbisb - SIN(abis)*cbisb
      ag1b = 0.5*abisb
      ag2b = 0.5*abisb
      CALL ATANC_BWD(yp(n), ypb(n), xp(n), xpb(n), ag1, ag1b, ag2b)
      ypb(1) = ypb(1) + xp(1)*ag1b/((-yp(1))**2+(-xp(1))**2)
      xpb(1) = xpb(1) - yp(1)*ag1b/((-yp(1))**2+(-xp(1))**2)
    ELSE
      dsteb = 0.0_8
      anteb = 0.0_8
      asteb = 0.0_8
    END IF
    DO j=n,1,-1
      CALL POPREAL8(bij(n+1, j))
      bijb(n+1, j) = 0.0_8
    END DO
    CALL POPREAL8(gamu(n+1, 2))
    gamub(n+1, 2) = 0.0_8
    CALL POPREAL8(gamu(n+1, 1))
    gamub(n+1, 1) = 0.0_8
    CALL POPREAL8(aij(n+1, n))
    aijb(n+1, n) = 0.0_8
    CALL POPREAL8(aij(n+1, 1))
    aijb(n+1, 1) = 0.0_8
    DO j=n+1,1,-1
      CALL POPREAL8(aij(n+1, j))
      aijb(n+1, j) = 0.0_8
    END DO
    dzdgb = 0.0_8
    DO i=n,1,-1
      CALL POPREAL8(gamu(i, 2))
      res2b = -gamub(i, 2)
      gamub(i, 2) = 0.0_8
      CALL POPREAL8(gamu(i, 1))
      res1b = -gamub(i, 1)
      gamub(i, 1) = 0.0_8
      CALL POPREAL8(aij(i, n+1))
      aijb(i, n+1) = 0.0_8
      DO j=n,1,-1
        CALL POPREAL8(bij(i, j))
        dzdmb(j) = dzdmb(j) - bijb(i, j)
        bijb(i, j) = 0.0_8
      END DO
      DO j=n,1,-1
        CALL POPREAL8(aij(i, j))
        dzdgb(j) = dzdgb(j) + aijb(i, j)
        aijb(i, j) = 0.0_8
      END DO
      xb0(i) = xb0(i) - qinf*res2b
      yb0(i) = yb0(i) + qinf*res1b
      qtan2b = 0.0_8
      qtan1b = 0.0_8
      xadtmpb1 = 0.0_8
      xadtmpb2 = 0.0_8
      CALL PSILIN_BWD(i, x(i), xadtmpb1, y(i), xadtmpb2, nx(i), nxb(i), ny(i               ), nyb(i), psi, &
&      psi_n, .false., .true.)
      xb0(i) = xb0(i) + xadtmpb1
      yb0(i) = yb0(i) + xadtmpb2
    END DO
    DO i=n,1,-1
      CALL POPREAL8(gamu(i, 2))
      CALL POPREAL8(gamu(i, 1))
      CALL POPREAL8(gam(i))
    END DO
  END SUBROUTINE GGCALC_BWD

!*==GGCALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE GGCALC()
    USE M_XSOLVE_DIFF, ONLY : ludcmp, baksub
    USE M_XUTILS_DIFF, ONLY : atanc
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: abis, ag1, ag2, bwt, cbis, ds1, ds2, dsmin, psi, psiinf, &
&   psi_n, qbis, res, res1, res2, sbis, xbis, ybis
    REAL :: nxbis
    INTEGER :: i, j, k
    REAL, DIMENSION(iqx) :: bcol
    INTRINSIC COS
    INTRINSIC SIN
    INTRINSIC ATAN2
    INTRINSIC SQRT
    INTRINSIC MIN
    INTEGER :: arg1
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!--------------------------------------------------------------
!     Calculates two surface vorticity (gamma) distributions
!     for alpha = 0, 90  degrees.  These are superimposed
!     in SPECAL or SPECCL for specified alpha or CL.
!--------------------------------------------------------------
!
!---- distance of internal control point ahead of sharp TE
!-    (fraction of smaller panel length adjacent to TE)
    bwt = 0.1
!
    IF (show_output) WRITE(*, *) &
&                    'Calculating unit vorticity distributions ...'
!
    DO i=1,n
      gam(i) = 0.
      gamu(i, 1) = 0.
      gamu(i, 2) = 0.
    END DO
    psio = 0.
!
!---- Set up matrix system for  Psi = Psio  on airfoil surface.
!-    The unknowns are (dGamma)i and dPsio.
    DO i=1,n
!
!------ calculate Psi and dPsi/dGamma array for current node
      CALL PSILIN(i, x(i), y(i), nx(i), ny(i), psi, psi_n, .false., &
&           .true.)
!
      psiinf = qinf*(COS(alfa)*y(i)-SIN(alfa)*x(i))
!
!------ RES1 = PSI( 0) - PSIO
!------ RES2 = PSI(90) - PSIO
      res1 = qinf*y(i)
      res2 = -(qinf*x(i))
!
!------ dRes/dGamma
      DO j=1,n
        aij(i, j) = dzdg(j)
      END DO
!
      DO j=1,n
        bij(i, j) = -dzdm(j)
      END DO
!
!------ dRes/dPsio
      aij(i, n+1) = -1.0
!
      gamu(i, 1) = -res1
      gamu(i, 2) = -res2
    END DO
!
!
!---- set Kutta condition
!-    RES = GAM(1) + GAM(N)
    res = 0.
!
    DO j=1,n+1
      aij(n+1, j) = 0.0
    END DO
!
    aij(n+1, 1) = 1.0
    aij(n+1, n) = 1.0
!
    gamu(n+1, 1) = -res
    gamu(n+1, 2) = -res
!
!---- set up Kutta condition (no direct source influence)
    DO j=1,n
      bij(n+1, j) = 0.
    END DO
!
    IF (sharp) THEN
!----- set zero internal velocity in TE corner
!
!----- set TE bisector angle
      ag1 = ATAN2(-yp(1), -xp(1))
      ag2 = ATANC(yp(n), xp(n), ag1)
      abis = 0.5*(ag1+ag2)
      cbis = COS(abis)
      sbis = SIN(abis)
!
!----- minimum panel length adjacent to TE
      ds1 = SQRT((x(1)-x(2))**2 + (y(1)-y(2))**2)
      ds2 = SQRT((x(n)-x(n-1))**2 + (y(n)-y(n-1))**2)
      IF (ds1 .GT. ds2) THEN
        dsmin = ds2
      ELSE
        dsmin = ds1
      END IF
!
!----- control point on bisector just ahead of TE point
      xbis = xte - bwt*dsmin*cbis
      ybis = yte - bwt*dsmin*sbis
!cc       write(*,*) xbis, ybis
!
!----- set velocity component along bisector line
! XFOILAD: normal passed through a variable (an expression argument
! becomes an undeclared temporary in Tapenade's split reverse code)
      nxbis = -sbis
      CALL PSILIN(0, xbis, ybis, nxbis, cbis, psi, qbis, .false., .true.&
&          )
!
!CC--- RES = DQDGj*Gammaj + DQDMj*Massj + QINF*(COSA*CBIS + SINA*SBIS)
      res = qbis
!
!----- dRes/dGamma
      DO j=1,n
        aij(n, j) = dqdg(j)
      END DO
!
!----- -dRes/dMass
      DO j=1,n
        bij(n, j) = -dqdm(j)
      END DO
!
!----- dRes/dPsio
      aij(n, n+1) = 0.
!
!----- -dRes/dUinf
      gamu(n, 1) = -cbis
!
!----- -dRes/dVinf
      gamu(n, 2) = -sbis
!
    END IF
!
!---- LU-factor coefficient matrix AIJ
    arg1 = n + 1
    CALL LUDCMP(iqx, arg1, aij, aijpiv)
    lqaij = .true.
!
!---- solve system for the two vorticity distributions
! XFOILAD: columns are copied to a work vector instead of being passed
! by sequence association (BIJ(1,j), GAMU(1,k)): Tapenade otherwise
! pushes/pops IQX*IZX values from that address and overruns the array.
    DO k=1,2
      DO i=1,iqx
        bcol(i) = gamu(i, k)
      END DO
      arg1 = n + 1
      CALL BAKSUB(iqx, arg1, aij, aijpiv, bcol)
      DO i=1,iqx
        gamu(i, k) = bcol(i)
      END DO
    END DO
!
!---- set inviscid alpha=0,90 surface speeds for this geometry
    DO i=1,n
      qinvu(i, 1) = gamu(i, 1)
      qinvu(i, 2) = gamu(i, 2)
    END DO
!
    lgamu = .true.
  END SUBROUTINE GGCALC

!  Differentiation of qwcalc in reverse (adjoint) mode, forward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILI
!N_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLC
!ALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile
!):
!   gradient     of useful results: dqdm dste qinvu x y nx ny ante
!                aste dzdm alfa apanel dqdg
!   with respect to varying inputs: dqdm dste qinvu x y nx ny ante
!                aste dzdm alfa apanel gamu dqdg
!*==QWCALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE QWCALC_FWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    INTEGER :: i
    REAL :: psi, psi_ni
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!---------------------------------------------------------------
!     Sets inviscid tangential velocity for alpha = 0, 90
!     on wake due to freestream and airfoil surface vorticity.
!---------------------------------------------------------------
!
!---- first wake point (same as TE)
    CALL PUSHREAL8(qinvu(n+1, 1))
    qinvu(n+1, 1) = qinvu(n, 1)
    CALL PUSHREAL8(qinvu(n+1, 2))
    qinvu(n+1, 2) = qinvu(n, 2)
!
!---- rest of wake
    DO i=n+2,n+nw
      CALL PSILIN_FWD(i, x(i), y(i), nx(i), ny(i), psi, psi_ni, .false.&
&               , .false.)
      CALL PUSHREAL8(qinvu(i, 1))
      qinvu(i, 1) = qtan1
      CALL PUSHREAL8(qinvu(i, 2))
      qinvu(i, 2) = qtan2
    END DO
  END SUBROUTINE QWCALC_FWD

!  Differentiation of qwcalc in reverse (adjoint) mode, backward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSIL
!IN_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CL
