      END DO
    END DO
!
!---- set up Kutta condition (no direct source influence)
    DO j=n+1,n+nw
      CALL PUSHREAL8(bij(n+1, j))
      bij(n+1, j) = 0.
    END DO
!
!---- sharp TE gamma extrapolation also has no source influence
    IF (sharp) THEN
      DO j=n+1,n+nw
        CALL PUSHREAL8(bij(n, j))
        bij(n, j) = 0.
      END DO
      CALL PUSHCONTROL1B(1)
    ELSE
      CALL PUSHCONTROL1B(0)
    END IF
!
!---- multiply by inverse of factored dPsi/dGam matrix
    DO j=n+1,n+nw
      DO k=1,iqx
        CALL PUSHREAL8(bcol(k))
        bcol(k) = bij(k, j)
      END DO
      arg1 = n + 1
      CALL BAKSUB_FWD(iqx, arg1, aij, aijpiv, bcol)
      DO k=1,iqx
        CALL PUSHREAL8(bij(k, j))
        bij(k, j) = bcol(k)
      END DO
    END DO
