      DO j=1,n
        sum = 0.
        DO k=1,n
          sum = sum + cij(iw, k)*dij(k, j)
        END DO
        CALL PUSHREAL8(dij(i, j))
        dij(i, j) = dij(i, j) + sum
      END DO
