    arg1 = waklen*chord
    CALL SETEXP_FWD(snw, ds1, arg1, nw)
    DO i=1,nw
      CALL PUSHREAL8(snew(n+i))
      snew(n+i) = snw(i)
    END DO
!
!      write(*,*) waklen, chord, waklen*chord
!      write(*,*) ds1
!      do i = n+1, n+nw
!        write(*,*) i-n, snew(i)
!      enddo
    CALL PUSHREAL8(xte)
    xte = 0.5*(x(1)+x(n))
    CALL PUSHREAL8(yte)
    yte = 0.5*(y(1)+y(n))
!
!---- set first wake point a tiny distance behind TE
    i = n + 1
    sx = 0.5*(yp(n)-yp(1))
    sy = 0.5*(xp(1)-xp(n))
    smod = SQRT(sx**2 + sy**2)
    CALL PUSHREAL8(nx(i))
    nx(i) = sx/smod
    CALL PUSHREAL8(ny(i))
    ny(i) = sy/smod
    CALL PUSHREAL8(x(i))
    x(i) = xte - 0.0001*ny(i)
    CALL PUSHREAL8(y(i))
    y(i) = yte + 0.0001*nx(i)
    tmp = s(n)
    CALL PUSHREAL8(s(i))
    s(i) = tmp
!
!---- calculate streamfunction gradient components at first point
    CALL PSILIN_XW_FWD(i, x(i), y(i), 1.0, 0.0, psi, psi_x, .false., &
&                .false.)
    CALL PSILIN_XW_FWD(i, x(i), y(i), 0.0, 1.0, psi, psi_y, .false., &
&                .false.)
!
!---- set unit vector normal to wake at first point
    CALL PUSHREAL8(nx(i+1))
    nx(i+1) = -(psi_x/SQRT(psi_x**2+psi_y**2))
    CALL PUSHREAL8(ny(i+1))
    ny(i+1) = -(psi_y/SQRT(psi_x**2+psi_y**2))
!
!---- set angle of wake panel normal
    CALL PUSHREAL8(apanel(i))
    apanel(i) = ATAN2(psi_y, psi_x)
    CALL PUSHINTEGER4(i)
!
!---- set rest of wake points
    DO i=n+2,n+nw
      ds = snew(i) - snew(i-1)
!
!------ set new point DS downstream of last point
      CALL PUSHREAL8(x(i))
      x(i) = x(i-1) - ds*ny(i)
      CALL PUSHREAL8(y(i))
      y(i) = y(i-1) + ds*nx(i)
      CALL PUSHREAL8(s(i))
      s(i) = s(i-1) + ds
!
      IF (i .NE. n + nw) THEN
!
!------- calculate normal vector for next point
        CALL PSILIN_XW_FWD(i, x(i), y(i), 1.0, 0.0, psi, psi_x, .false.&
&                    , .false.)
        CALL PSILIN_XW_FWD(i, x(i), y(i), 0.0, 1.0, psi, psi_y, .false.&
&                    , .false.)
!
        CALL PUSHREAL8(nx(i+1))
        nx(i+1) = -(psi_x/SQRT(psi_x**2+psi_y**2))
        CALL PUSHREAL8(ny(i+1))
        ny(i+1) = -(psi_y/SQRT(psi_x**2+psi_y**2))
!
!------- set angle of wake panel normal
        CALL PUSHREAL8(apanel(i))
        apanel(i) = ATAN2(psi_y, psi_x)
        CALL PUSHCONTROL1B(1)
      ELSE
        CALL PUSHCONTROL1B(0)
      END IF
    END DO
!
!
!---- set wake presence flag and corresponding alpha
    lwake = .true.
!
!---- old source influence matrix is invalid for the new wake geometry
    lwdij = .false.
    CALL PUSHREAL8(psi_y)
    CALL PUSHREAL8(psi_x)
    CALL PUSHREAL8(smod)
  END SUBROUTINE XYWAKE_FWD

!  Differentiation of xywake in reverse (adjoint) mode, backward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSIL
!IN_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CL
!CALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFil
!e):
