  SUBROUTINE XYWAKE_BWD()
    USE M_XUTILS_DIFF, ONLY : setexp, setexp_fwd, setexp_bwd
    USE I_XFOIL_DIFF
    IMPLICIT NONE
    REAL(kind=8) :: xadtmpb1, xadtmpb2, xadtmpb3, xadtmpb4, xadtmpb5, xadtmpb6, xadtmpb7, xadtmpb8
!
    REAL :: ds, ds1, psi, psi_x, psi_y, smod, sx, sy
    REAL :: dsb, ds1b, psi_xb, psi_yb, smodb, sxb, syb
    INTEGER :: i
    REAL, DIMENSION(iwx) :: snw
    REAL, DIMENSION(iwx) :: snwb
    INTRINSIC INT
    INTRINSIC SQRT
    INTRINSIC ATAN2
    REAL :: arg1
    REAL :: arg1b
    REAL :: temp
    REAL :: tempb
    REAL :: tmpb
    REAL :: temp0
    REAL :: tempb0
    INTEGER :: branch
    CALL POPREAL8(smod)
    CALL POPREAL8(psi_x)
    CALL POPREAL8(psi_y)
    snewb = 0.0_8
    DO i=n+nw,n+2,-1
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        temp0 = psi_x*psi_x + psi_y*psi_y
        temp = SQRT(temp0)
        IF (temp0 .EQ. 0.0_8) THEN
          tempb0 = 0.0_8
        ELSE
          tempb0 = psi_y*nyb(i+1)/(2.0*temp**3)
        END IF
        CALL POPREAL8(apanel(i))
        psi_yb = psi_x*apanelb(i)/(psi_y**2+psi_x**2) + 2*psi_y*tempb0 -&
&         nyb(i+1)/temp
        psi_xb = 2*psi_x*tempb0 - psi_y*apanelb(i)/(psi_y**2+psi_x**2)
        apanelb(i) = 0.0_8
        CALL POPREAL8(ny(i+1))
        nyb(i+1) = 0.0_8
        CALL POPREAL8(nx(i+1))
        temp0 = psi_x*psi_x + psi_y*psi_y
        temp = SQRT(temp0)
        IF (temp0 .EQ. 0.0_8) THEN
          tempb0 = 0.0_8
        ELSE
          tempb0 = psi_x*nxb(i+1)/(2.0*temp**3)
        END IF
        psi_xb = psi_xb + 2*psi_x*tempb0 - nxb(i+1)/temp
        nxb(i+1) = 0.0_8
        psi_yb = psi_yb + 2*psi_y*tempb0
        xadtmpb1 = 0.0_8
        xadtmpb2 = 0.0_8
        CALL PSILIN_XW_BWD(i, x(i), xadtmpb1, y(i), xadtmpb2, 0.0, 1.0, psi, psi_y, psi_yb, .false., .false.)
        xb0(i) = xb0(i) + xadtmpb1
        yb0(i) = yb0(i) + xadtmpb2
        xadtmpb3 = 0.0_8
        xadtmpb4 = 0.0_8
        CALL PSILIN_XW_BWD(i, x(i), xadtmpb3, y(i), xadtmpb4, 1.0, 0.0, psi, psi_x, psi_xb, .false., .false.)
        xb0(i) = xb0(i) + xadtmpb3
        yb0(i) = yb0(i) + xadtmpb4
      END IF
      ds = snew(i) - snew(i-1)
      CALL POPREAL8(s(i))
      sb0(i-1) = sb0(i-1) + sb0(i)
      dsb = sb0(i) + nx(i)*yb0(i) - ny(i)*xb0(i)
      sb0(i) = 0.0_8
      CALL POPREAL8(y(i))
      yb0(i-1) = yb0(i-1) + yb0(i)
      nxb(i) = nxb(i) + ds*yb0(i)
      yb0(i) = 0.0_8
      CALL POPREAL8(x(i))
      xb0(i-1) = xb0(i-1) + xb0(i)
      nyb(i) = nyb(i) - ds*xb0(i)
      xb0(i) = 0.0_8
      snewb(i) = snewb(i) + dsb
      snewb(i-1) = snewb(i-1) - dsb
    END DO
    CALL POPINTEGER4(i)
    sx = 0.5*(yp(n)-yp(1))
    temp0 = psi_x*psi_x + psi_y*psi_y
    temp = SQRT(temp0)
    i = n + 1
    CALL POPREAL8(apanel(i))
    psi_yb = psi_x*apanelb(i)/(psi_y**2+psi_x**2) - nyb(i+1)/temp
    CALL POPREAL8(ny(i+1))
    IF (temp0 .EQ. 0.0_8) THEN
      tempb0 = 0.0_8
    ELSE
      tempb0 = psi_y*nyb(i+1)/(2.0*temp**3)
    END IF
    nyb(i+1) = 0.0_8
    CALL POPREAL8(nx(i+1))
    temp = psi_x*psi_x + psi_y*psi_y
    temp0 = SQRT(temp)
    IF (temp .EQ. 0.0_8) THEN
      tempb = 0.0_8
    ELSE
      tempb = psi_x*nxb(i+1)/(2.0*temp0**3)
    END IF
    psi_xb = 2*psi_x*tempb0 - psi_y*apanelb(i)/(psi_y**2+psi_x**2) + 2*&
&     psi_x*tempb - nxb(i+1)/temp0
    apanelb(i) = 0.0_8
    psi_yb = psi_yb + 2*psi_y*tempb0 + 2*psi_y*tempb
    nxb(i+1) = 0.0_8
    xadtmpb5 = 0.0_8
    xadtmpb6 = 0.0_8
    CALL PSILIN_XW_BWD(i, x(i), xadtmpb5, y(i), xadtmpb6, 0.0, 1.0, psi, psi_y, psi_yb, .false., .false.)
    xb0(i) = xb0(i) + xadtmpb5
    yb0(i) = yb0(i) + xadtmpb6
    xadtmpb7 = 0.0_8
    xadtmpb8 = 0.0_8
    CALL PSILIN_XW_BWD(i, x(i), xadtmpb7, y(i), xadtmpb8, 1.0, 0.0, psi, psi_x, psi_xb, .false., .false.)
    xb0(i) = xb0(i) + xadtmpb7
    yb0(i) = yb0(i) + xadtmpb8
    CALL POPREAL8(s(i))
    tmpb = sb0(i)
    sb0(i) = 0.0_8
    sb0(n) = sb0(n) + tmpb
    CALL POPREAL8(y(i))
    yteb = yteb + yb0(i)
    nxb(i) = nxb(i) + 0.0001*yb0(i)
    yb0(i) = 0.0_8
    CALL POPREAL8(x(i))
    xteb = xteb + xb0(i)
    nyb(i) = nyb(i) - 0.0001*xb0(i)
    xb0(i) = 0.0_8
    sy = 0.5*(xp(1)-xp(n))
    CALL POPREAL8(ny(i))
    smodb = -(sy*nyb(i)/smod**2) - sx*nxb(i)/smod**2
    CALL POPREAL8(nx(i))
    IF (sx**2 + sy**2 .EQ. 0.0_8) THEN
      tempb = 0.0_8
    ELSE
      tempb = smodb/(2.0*SQRT(sx**2+sy**2))
    END IF
    syb = nyb(i)/smod + 2*sy*tempb
    nyb(i) = 0.0_8
    sxb = nxb(i)/smod + 2*sx*tempb
    nxb(i) = 0.0_8
    xpb(1) = xpb(1) + 0.5*syb
    xpb(n) = xpb(n) - 0.5*syb
    ypb(n) = ypb(n) + 0.5*sxb
    ypb(1) = ypb(1) - 0.5*sxb
    CALL POPREAL8(yte)
    yb0(1) = yb0(1) + 0.5*yteb
    yb0(n) = yb0(n) + 0.5*yteb
    CALL POPREAL8(xte)
    xb0(1) = xb0(1) + 0.5*xteb
    xb0(n) = xb0(n) + 0.5*xteb
    snwb = 0.0_8
    DO i=nw,1,-1
      CALL POPREAL8(snew(n+i))
      snwb(i) = snwb(i) + snewb(n+i)
      snewb(n+i) = 0.0_8
    END DO
    ds1 = 0.5*(s(2)-s(1)+s(n)-s(n-1))
    arg1 = waklen*chord
    CALL SETEXP_BWD(snw, snwb, ds1, ds1b, arg1, arg1b, nw)
    chordb0 = waklen*arg1b
    tempb = 0.5*ds1b
    sb0(2) = sb0(2) + tempb
    sb0(1) = sb0(1) - tempb
    sb0(n) = sb0(n) + tempb
    sb0(n-1) = sb0(n-1) - tempb
    CALL POPCONTROL1B(branch)
    CALL POPINTEGER4(nw)
  END SUBROUTINE XYWAKE_BWD

