!---- number of wake points
    nw = n/12 + 10*INT(waklen)
    IF (nw .GT. iwx) THEN
      IF (show_output) WRITE(*, *) &
&          'Array size (IWX) too small.  Last wake point index reduced.'
      nw = iwx
    END IF
!
    ds1 = 0.5*(s(2)-s(1)+s(n)-s(n-1))
! XFOILAD: work vector instead of SNEW(N+1) (sequence association, see QDCALC)
    arg1 = waklen*chord
    CALL SETEXP(snw, ds1, arg1, nw)
    DO i=1,nw
      snew(n+i) = snw(i)
    END DO
!
!      write(*,*) waklen, chord, waklen*chord
!      write(*,*) ds1
!      do i = n+1, n+nw
!        write(*,*) i-n, snew(i)
!      enddo
    xte = 0.5*(x(1)+x(n))
    yte = 0.5*(y(1)+y(n))
!
!---- set first wake point a tiny distance behind TE
    i = n + 1
    sx = 0.5*(yp(n)-yp(1))
    sy = 0.5*(xp(1)-xp(n))
    smod = SQRT(sx**2 + sy**2)
    nx(i) = sx/smod
    ny(i) = sy/smod
    x(i) = xte - 0.0001*ny(i)
    y(i) = yte + 0.0001*nx(i)
    s(i) = s(n)
!
