!  Differentiation of stfind in reverse (adjoint) mode, forward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILI
!N_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLC
!ALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile
!):
!   gradient     of useful results: s sst_go sst_gp sst gam
!   with respect to varying inputs: s gam
!*==STFIND.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE STFIND_FWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: dgam, ds
    INTEGER :: i
    INTEGER :: ad_count
    ad_count = 1
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------
!     Locates stagnation point arc length
!     location SST and panel index IST.
!-----------------------------------------
!
    DO i=1,n-1
      IF (gam(i) .GE. 0.0 .AND. gam(i+1) .LT. 0.0) THEN
        GOTO 110
      ELSE
        ad_count = ad_count + 1
      END IF
    END DO
    CALL PUSHCONTROL1B(0)
    CALL PUSHINTEGER4(ad_count)
!
    IF (show_output) THEN
      CALL PUSHCONTROL1B(1)
      WRITE(*, *) 'STFIND: Stagnation point not found. Continuing ...'
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
    i = n/2
    GOTO 100
 110 CALL PUSHCONTROL1B(1)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL1B(0)
!
!
 100 ist = i
    dgam = gam(i+1) - gam(i)
    ds = s(i+1) - s(i)
!
!---- evaluate so as to minimize roundoff for very small GAM(I) or GAM(I+1)
    IF (gam(i) .LT. -gam(i+1)) THEN
      CALL PUSHREAL8(sst)
      sst = s(i) - ds*(gam(i)/dgam)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHREAL8(sst)
      sst = s(i+1) - ds*(gam(i+1)/dgam)
      CALL PUSHCONTROL1B(1)
    END IF
!
    CALL PUSHREAL8(sst_go)
    sst_go = (sst-s(i+1))/dgam
    CALL PUSHREAL8(sst_gp)
    sst_gp = (s(i)-sst)/dgam
!
!---- XFOILAD: keep the stagnation point at least STFRAC panel lengths from
!     both nodes.  When it falls (nearly) on a node, e.g. a symmetric section
!     at alpha = 0 with a node at the LE, the first BL station of one side is
!     at xi ~ 0 with Ue ~ 0, and the similarity station makes the Newton system
!     singular (XFOIL's original tweak moved it by only 1e-7).  The clamped
!     stagnation point no longer depends on GAM.
    IF (sst .LT. s(i) + stfrac*ds) THEN
      CALL PUSHREAL8(sst)
      sst = s(i) + stfrac*ds
      sst_go = 0.
      sst_gp = 0.
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
    IF (sst .GT. s(i+1) - stfrac*ds) THEN
      CALL PUSHREAL8(sst)
      sst = s(i+1) - stfrac*ds
      sst_go = 0.
      sst_gp = 0.
      CALL PUSHREAL8(dgam)
      CALL PUSHINTEGER4(i)
      CALL PUSHCONTROL1B(1)
    ELSE
      CALL PUSHREAL8(dgam)
      CALL PUSHREAL8(ds)
      CALL PUSHINTEGER4(i)
      CALL PUSHCONTROL1B(0)
    END IF
  END SUBROUTINE STFIND_FWD

