    tempb = sst_gpb/dgam
    sb0(i) = sb0(i) + tempb
    sstb = sstb - tempb
    dgamb = -((s(i)-sst)*tempb/dgam)
    CALL POPREAL8(sst_go)
    tempb = sst_gob/dgam
    sstb = sstb + tempb
    sb0(i+1) = sb0(i+1) - tempb
    dgamb = dgamb - (sst-s(i+1))*tempb/dgam
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(sst)
      sb0(i) = sb0(i) + sstb
      gamb(i) = gamb(i) - ds*sstb/dgam
      tempb = -(gam(i)*sstb/dgam)
      dsb = dsb + tempb
      dgamb = dgamb - ds*tempb/dgam
    ELSE
      CALL POPREAL8(sst)
      sb0(i+1) = sb0(i+1) + sstb
      gamb(i+1) = gamb(i+1) - ds*sstb/dgam
      tempb = -(gam(i+1)*sstb/dgam)
      dsb = dsb + tempb
      dgamb = dgamb - ds*tempb/dgam
    END IF
    sb0(i+1) = sb0(i+1) + dsb
    sb0(i) = sb0(i) - dsb
    gamb(i+1) = gamb(i+1) + dgamb
    gamb(i) = gamb(i) - dgamb
    CALL POPCONTROL1B(branch)
    CALL POPINTEGER4(ad_count)
    DO i0=1,ad_count
      IF (i0 .EQ. 1) CALL POPCONTROL1B(branch)
    END DO
  END SUBROUTINE STFIND_BWD

!*==STFIND.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE STFIND()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: dgam, ds
    INTEGER :: i
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-----------------------------------------
!     Locates stagnation point arc length
!     location SST and panel index IST.
!-----------------------------------------
!
    DO i=1,n-1
      IF (gam(i) .GE. 0.0 .AND. gam(i+1) .LT. 0.0) GOTO 100
    END DO
!
    IF (show_output) WRITE(*, *) &
&                   'STFIND: Stagnation point not found. Continuing ...'
    i = n/2
!
!
 100 ist = i
    dgam = gam(i+1) - gam(i)
    ds = s(i+1) - s(i)
!
!---- evaluate so as to minimize roundoff for very small GAM(I) or GAM(I+1)
    IF (gam(i) .LT. -gam(i+1)) THEN
      sst = s(i) - ds*(gam(i)/dgam)
    ELSE
      sst = s(i+1) - ds*(gam(i+1)/dgam)
    END IF
!
    sst_go = (sst-s(i+1))/dgam
    sst_gp = (s(i)-sst)/dgam
!
!---- XFOILAD: keep the stagnation point at least STFRAC panel lengths from
!     both nodes.  When it falls (nearly) on a node, e.g. a symmetric section
!     at alpha = 0 with a node at the LE, the first BL station of one side is
!     at xi ~ 0 with Ue ~ 0, and the similarity station makes the Newton system
!     singular (XFOIL's original tweak moved it by only 1e-7).  The clamped
!     stagnation point no longer depends on GAM.
    IF (sst .LT. s(i) + stfrac*ds) THEN
      sst = s(i) + stfrac*ds
      sst_go = 0.
      sst_gp = 0.
    END IF
    IF (sst .GT. s(i+1) - stfrac*ds) THEN
      sst = s(i+1) - stfrac*ds
      sst_go = 0.
      sst_gp = 0.
    END IF
  END SUBROUTINE STFIND

!*==IBLPAN.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE IBLPAN()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    INTEGER :: i, ibl, iblmax, is, iw
    INTRINSIC MAX
    INTEGER :: max1
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-------------------------------------------------------------
!     Sets  BL location -> panel location  pointer array IPAN
!-------------------------------------------------------------
!
!---- top surface first
    is = 1
!
    ibl = 1
    DO i=ist,1,-1
      ibl = ibl + 1
      ipan(ibl, is) = i
      vti(ibl, is) = 1.0
    END DO
!
    iblte(is) = ibl
    nbl(is) = ibl
!
!---- bottom surface next
    is = 2
!
    ibl = 1
    DO i=ist+1,n
      ibl = ibl + 1
      ipan(ibl, is) = i
      vti(ibl, is) = -1.0
    END DO
!
!---- wake
    iblte(is) = ibl
!
    DO iw=1,nw
      i = n + iw
      ibl = iblte(is) + iw
      ipan(ibl, is) = i
      vti(ibl, is) = -1.0
    END DO
!
    nbl(is) = iblte(is) + nw
!
!---- upper wake pointers (for plotting only)
    DO iw=1,nw
      ipan(iblte(1)+iw, 1) = ipan(iblte(2)+iw, 2)
      vti(iblte(1)+iw, 1) = 1.0
    END DO
    IF (iblte(1) .LT. iblte(2)) THEN
      max1 = iblte(2)
    ELSE
      max1 = iblte(1)
    END IF
!
!
    iblmax = max1 + nw
    IF (iblmax .GT. ivx) THEN
      IF (show_output) THEN
        WRITE(*, *) ' ***  BL array overflow.'
        WRITE(*, *) ' ***  Increase IVX to at least', iblmax
      END IF
      STOP
    ELSE
!
      lipan = .true.
    END IF
  END SUBROUTINE IBLPAN

!  Differentiation of xicalc in reverse (adjoint) mode, forward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILI
!N_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLC
!ALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile
!):
!   gradient     of useful results: xssi s x y wgap xp ante yp
!                sst
!   with respect to varying inputs: xssi s x y wgap xp ante yp
!                sst
!*==XICALC.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE XICALC_FWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: aa, bb, crosp, dwdxte, dxssi, telrat, xeps, zn
    INTEGER :: i, ibl, ibl1, ibl2, is, is1, is2, iw
    REAL, SAVE :: xfeps
    INTRINSIC MAX
    INTRINSIC SQRT
    INTRINSIC MIN
    INTEGER :: ad_from
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-------------------------------------------------------------
!     Sets BL arc length array on each airfoil side and wake
!-------------------------------------------------------------
    DATA xfeps /1.0e-7/
!
!---- minimum xi node arc length near stagnation point
    xeps = xfeps*(s(n)-s(1))
!
    is = 1
!
    CALL PUSHREAL8(xssi(1, is))
    xssi(1, is) = 0.
!
    DO ibl=2,iblte(is)
      i = ipan(ibl, is)
      IF (sst - s(i) .LT. xeps) THEN
        CALL PUSHREAL8(xssi(ibl, is))
        xssi(ibl, is) = xeps
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(xssi(ibl, is))
        xssi(ibl, is) = sst - s(i)
        CALL PUSHCONTROL1B(1)
      END IF
    END DO
    CALL PUSHINTEGER4(ibl - 1)
!
!
    is = 2
!
    CALL PUSHREAL8(xssi(1, is))
    xssi(1, is) = 0.
!
    DO ibl=2,iblte(is)
      i = ipan(ibl, is)
      IF (s(i) - sst .LT. xeps) THEN
        CALL PUSHREAL8(xssi(ibl, is))
        xssi(ibl, is) = xeps
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(xssi(ibl, is))
        xssi(ibl, is) = s(i) - sst
        CALL PUSHCONTROL1B(1)
      END IF
    END DO
    CALL PUSHINTEGER4(ibl - 1)
!
!
    is1 = 1
    is2 = 2
!
    ibl1 = iblte(is1) + 1
    CALL PUSHREAL8(xssi(ibl1, is1))
    xssi(ibl1, is1) = xssi(ibl1-1, is1)
!
    ibl2 = iblte(is2) + 1
    CALL PUSHREAL8(xssi(ibl2, is2))
    xssi(ibl2, is2) = xssi(ibl2-1, is2)
    ad_from = iblte(is) + 2
!
    DO ibl=ad_from,nbl(is)
      i = ipan(ibl, is)
      dxssi = SQRT((x(i)-x(i-1))**2 + (y(i)-y(i-1))**2)
!
      ibl1 = iblte(is1) + ibl - iblte(is)
      ibl2 = iblte(is2) + ibl - iblte(is)
      CALL PUSHREAL8(xssi(ibl1, is1))
      xssi(ibl1, is1) = xssi(ibl1-1, is1) + dxssi
      CALL PUSHREAL8(xssi(ibl2, is2))
      xssi(ibl2, is2) = xssi(ibl2-1, is2) + dxssi
    END DO
    CALL PUSHINTEGER4(ibl - 1)
    CALL PUSHINTEGER4(ad_from)
!
!---- trailing edge flap length to TE gap ratio
    telrat = 2.50
!
!---- set up parameters for TE flap cubics
!
!cc   DWDXTE = YP(1)/XP(1) + YP(N)/XP(N)    !!! BUG  2/2/95
!
    crosp = (xp(1)*yp(n)-yp(1)*xp(n))/SQRT((xp(1)**2+yp(1)**2)*(xp(n)**2&
&     +yp(n)**2))
    dwdxte = crosp/SQRT(1.0-crosp**2)
    IF (dwdxte .LT. -(3.0/telrat)) THEN
      dwdxte = -(3.0/telrat)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      dwdxte = dwdxte
    END IF
    IF (dwdxte .GT. 3.0/telrat) THEN
      dwdxte = 3.0/telrat
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      dwdxte = dwdxte
    END IF
!
    aa = 3.0 + telrat*dwdxte
    bb = -2.0 - telrat*dwdxte
!
    IF (sharp) THEN
      DO iw=1,nw
        CALL PUSHREAL8(wgap(iw))
        wgap(iw) = 0.
      END DO
      CALL PUSHREAL8(telrat)
      CALL PUSHREAL8(crosp)
      CALL PUSHCONTROL1B(0)
    ELSE
!----- set TE flap (wake gap) array
      is = 2
      DO iw=1,nw
        CALL PUSHINTEGER4(ibl)
        ibl = iblte(is) + iw
        zn = 1.0 - (xssi(ibl, is)-xssi(iblte(is), is))/(telrat*ante)
        CALL PUSHREAL8(wgap(iw))
        wgap(iw) = 0.
        IF (zn .GE. 0.0) THEN
          wgap(iw) = ante*(aa+bb*zn)*zn**2
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
      END DO
      CALL PUSHINTEGER4(is)
      CALL PUSHINTEGER4(ibl)
      CALL PUSHREAL8(telrat)
      CALL PUSHREAL8(bb)
      CALL PUSHREAL8(aa)
      CALL PUSHREAL8(crosp)
      CALL PUSHCONTROL1B(1)
    END IF
