  SUBROUTINE XICALC_BWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
    REAL :: aa, bb, crosp, dwdxte, dxssi, telrat, xeps, zn
    REAL :: aab, bbb, crospb, dwdxteb, dxssib, xepsb, znb
    INTEGER :: i, ibl, ibl1, ibl2, is, is1, is2, iw
    REAL, SAVE :: xfeps
