    REAL :: tempb
    REAL :: temp0
    REAL :: tempb0
    REAL :: temp1
    REAL :: tempb1
    REAL :: tempb2
    REAL :: temp2
    REAL :: tempb3
    INTEGER :: ad_to
    INTEGER :: branch
    INTEGER :: ad_to0
    INTEGER :: ad_from
    INTEGER :: ad_to1
    DATA xfeps /1.0e-7/
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      CALL POPREAL8(crosp)
      CALL POPREAL8(telrat)
      DO iw=nw,1,-1
        CALL POPREAL8(wgap(iw))
        wgapb(iw) = 0.0_8
      END DO
      aab = 0.0_8
      bbb = 0.0_8
    ELSE
      CALL POPREAL8(crosp)
      CALL POPREAL8(aa)
      CALL POPREAL8(bb)
      CALL POPREAL8(telrat)
      CALL POPINTEGER4(ibl)
      CALL POPINTEGER4(is)
      aab = 0.0_8
      bbb = 0.0_8
      DO iw=nw,1,-1
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          znb = 0.0_8
        ELSE
          ibl = iblte(is) + iw
          zn = 1.0 - (xssi(ibl, is)-xssi(iblte(is), is))/(telrat*ante)
          tempb3 = ante*zn**2*wgapb(iw)
          tempb2 = (aa+bb*zn)*wgapb(iw)
          wgapb(iw) = 0.0_8
          anteb = anteb + zn**2*tempb2
          znb = 2*zn*ante*tempb2 + bb*tempb3
          aab = aab + tempb3
          bbb = bbb + zn*tempb3
        END IF
        CALL POPREAL8(wgap(iw))
        wgapb(iw) = 0.0_8
        tempb3 = -(znb/(telrat*ante))
        xssib(ibl, is) = xssib(ibl, is) + tempb3
        xssib(iblte(is), is) = xssib(iblte(is), is) - tempb3
        anteb = anteb - (xssi(ibl, is)-xssi(iblte(is), is))*tempb3/ante
        CALL POPINTEGER4(ibl)
