      crospb = (1.0/temp2+2*crosp**2/(2.0*temp2**3))*dwdxteb
    END IF
    temp1 = xp(n)*xp(n) + yp(n)*yp(n)
    temp0 = xp(1)*xp(1) + yp(1)*yp(1)
    temp = SQRT(temp0*temp1)
    tempb2 = crospb/temp
    xpb(1) = xpb(1) + yp(n)*tempb2
    ypb(n) = ypb(n) + xp(1)*tempb2
    xpb(n) = xpb(n) - yp(1)*tempb2
    IF (temp0*temp1 .EQ. 0.0_8) THEN
      tempb3 = 0.0_8
    ELSE
      tempb3 = -((xp(1)*yp(n)-yp(1)*xp(n))*tempb2/(2.0*temp**2))
    END IF
    ypb(1) = ypb(1) + 2*yp(1)*temp1*tempb3 - xp(n)*tempb2
    xpb(1) = xpb(1) + 2*xp(1)*temp1*tempb3
    xpb(n) = xpb(n) + 2*xp(n)*temp0*tempb3
