      xssib(ibl1-1, is1) = xssib(ibl1-1, is1) + xssib(ibl1, is1)
      dxssib = dxssib + xssib(ibl1, is1)
      xssib(ibl1, is1) = 0.0_8
      i = ipan(ibl, is)
      IF ((x(i)-x(i-1))**2 + (y(i)-y(i-1))**2 .EQ. 0.0_8) THEN
        tempb = 0.0_8
      ELSE
        tempb = dxssib/(2.0*SQRT((x(i)-x(i-1))**2+(y(i)-y(i-1))**2))
      END IF
      tempb0 = 2*(x(i)-x(i-1))*tempb
      tempb1 = 2*(y(i)-y(i-1))*tempb
      yb0(i) = yb0(i) + tempb1
      yb0(i-1) = yb0(i-1) - tempb1
      xb0(i) = xb0(i) + tempb0
      xb0(i-1) = xb0(i-1) - tempb0
    END DO
    ibl2 = iblte(is2) + 1
    CALL POPREAL8(xssi(ibl2, is2))
    xssib(ibl2-1, is2) = xssib(ibl2-1, is2) + xssib(ibl2, is2)
    xssib(ibl2, is2) = 0.0_8
    ibl1 = iblte(is1) + 1
    CALL POPREAL8(xssi(ibl1, is1))
    xssib(ibl1-1, is1) = xssib(ibl1-1, is1) + xssib(ibl1, is1)
    xssib(ibl1, is1) = 0.0_8
    xepsb = 0.0_8
    CALL POPINTEGER4(ad_to0)
    DO ibl=ad_to0,2,-1
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(xssi(ibl, is))
        xepsb = xepsb + xssib(ibl, is)
        xssib(ibl, is) = 0.0_8
