    END DO
    CALL POPREAL8(xssi(1, is))
    xssib(1, is) = 0.0_8
    is = 1
    CALL POPINTEGER4(ad_to)
    DO ibl=ad_to,2,-1
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(xssi(ibl, is))
        xepsb = xepsb + xssib(ibl, is)
        xssib(ibl, is) = 0.0_8
      ELSE
        i = ipan(ibl, is)
        CALL POPREAL8(xssi(ibl, is))
        sstb = sstb + xssib(ibl, is)
        sb0(i) = sb0(i) - xssib(ibl, is)
        xssib(ibl, is) = 0.0_8
      END IF
    END DO
    CALL POPREAL8(xssi(1, is))
    xssib(1, is) = 0.0_8
    sb0(n) = sb0(n) + xfeps*xepsb
    sb0(1) = sb0(1) - xfeps*xepsb
  END SUBROUTINE XICALC_BWD

