  SUBROUTINE UICALC_BWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
    INTEGER :: i, ibl, is
    INTEGER :: ad_to
    DO is=2,1,-1
      CALL POPINTEGER4(ad_to)
      DO ibl=ad_to,2,-1
        i = ipan(ibl, is)
        CALL POPREAL8(uinv_a(ibl, is))
        qinv_ab(i) = qinv_ab(i) + vti(ibl, is)*uinv_ab(ibl, is)
        uinv_ab(ibl, is) = 0.0_8
        CALL POPREAL8(uinv(ibl, is))
        qinvb(i) = qinvb(i) + vti(ibl, is)*uinvb(ibl, is)
        uinvb(ibl, is) = 0.0_8
      END DO
      CALL POPREAL8(uinv_a(1, is))
      uinv_ab(1, is) = 0.0_8
      CALL POPREAL8(uinv(1, is))
      uinvb(1, is) = 0.0_8
    END DO
  END SUBROUTINE UICALC_BWD

