!  Differentiation of qiset in reverse (adjoint) mode, forward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILIN
!_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLCA
!LC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile)
!:
!   gradient     of useful results: qinvu qinv qinv_a alfa
!   with respect to varying inputs: qinvu qinv qinv_a alfa
!*==QISET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE QISET_FWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    INTEGER :: i
    INTRINSIC COS
    INTRINSIC SIN
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!-------------------------------------------------------
!     Sets inviscid panel tangential velocity for
!     current alpha.
!-------------------------------------------------------
!
    CALL PUSHREAL8(cosa)
    cosa = COS(alfa)
    CALL PUSHREAL8(sina)
    sina = SIN(alfa)
!
    DO i=1,n+nw
      CALL PUSHREAL8(qinv(i))
      qinv(i) = cosa*qinvu(i, 1) + sina*qinvu(i, 2)
      qinv_a(i) = -(sina*qinvu(i, 1)) + cosa*qinvu(i, 2)
    END DO
  END SUBROUTINE QISET_FWD

!  Differentiation of qiset in reverse (adjoint) mode, backward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILI
!N_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLC
!ALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile
!):
!   gradient     of useful results: qinvu qinv qinv_a alfa
!   with respect to varying inputs: qinvu qinv qinv_a alfa
!*==QISET.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE QISET_BWD()
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
    INTEGER :: i
    INTRINSIC COS
    INTRINSIC SIN
    cosab = 0.0_8
    sinab = 0.0_8
    DO i=n+nw,1,-1
      cosab = cosab + qinvu(i, 2)*qinv_ab(i) + qinvu(i, 1)*qinvb(i)
      qinvub(i, 2) = qinvub(i, 2) + cosa*qinv_ab(i) + sina*qinvb(i)
      sinab = sinab + qinvu(i, 2)*qinvb(i) - qinvu(i, 1)*qinv_ab(i)
      qinvub(i, 1) = qinvub(i, 1) + cosa*qinvb(i) - sina*qinv_ab(i)
      qinv_ab(i) = 0.0_8
      CALL POPREAL8(qinv(i))
      qinvb(i) = 0.0_8
    END DO
    CALL POPREAL8(sina)
    alfab = alfab + COS(alfa)*sinab - SIN(alfa)*cosab
    CALL POPREAL8(cosa)
  END SUBROUTINE QISET_BWD

