!  Differentiation of stmove in reverse (adjoint) mode, forward sweep (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILI
!N_XW PSWLIN QDCALC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLC
!ALC CDCALC CPCALC QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile
!):
!   gradient     of useful results: xssi ctau uedg s qinv mass
!                x y qinv_a dstr uinv_a wgap xp ante sst_go sst_gp
!                thet qvis yp uinv sst gam
!   with respect to varying inputs: xssi ctau uedg s qinv mass
!                x y qinv_a dstr uinv_a wgap xp ante thet qvis
!                yp uinv gam
!*==STMOVE.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE STMOVE_FWD()
    USE S_XBL_DIFF, ONLY : iblsys
    USE I_XFOIL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: dudx, ueps
    INTEGER :: i, ibl, idif, is, istold
    REAL :: tmp
    REAL :: tmp0
    REAL :: tmp1
    REAL :: tmp2
    REAL :: tmp3
    REAL :: tmp4
    REAL :: tmp5
    REAL :: tmp6
    REAL :: tmp7
    REAL :: tmp8
    REAL :: tmp9
    REAL :: tmp10
    REAL :: tmp11
    REAL :: tmp12
    REAL :: tmp13
    REAL :: tmp14
    REAL :: tmp15
    REAL :: tmp16
    REAL :: tmp17
    REAL :: tmp18
    REAL :: tmp19
    REAL :: tmp20
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!---------------------------------------------------
!     Moves stagnation point location to new panel.
!---------------------------------------------------
!
!---- locate new stagnation point arc length SST from GAM distribution
    istold = ist
    CALL STFIND_FWD()
!
    IF (istold .EQ. ist) THEN
!
!----- recalculate new arc length array
      CALL XICALC_FWD()
!
      CALL PUSHCONTROL1B(1)
    ELSE
!
!CC       WRITE(*,*) 'STMOVE: Resetting stagnation point'
!
!----- set new BL position -> panel position  pointers
      CALL PUSHREAL8ARRAY(vti, ivx*isx)
      CALL PUSHINTEGER4ARRAY(nbl, isx)
      CALL PUSHINTEGER4ARRAY(iblte, isx)
      CALL PUSHINTEGER4ARRAY(ipan, ivx*isx)
      CALL IBLPAN()
!
!----- set new inviscid BL edge velocity UINV from QINV
      CALL UICALC_FWD()
!
!----- recalculate new arc length array
      CALL XICALC_FWD()
!
!----- set  BL position -> system line  pointers
      CALL PUSHINTEGER4(nsys)
      CALL PUSHINTEGER4ARRAY(isys, ivx*isx)
      CALL IBLSYS()
!
      IF (ist .GT. istold) THEN
!------ increase in number of points on top side (IS=1)
        idif = ist - istold
!
        CALL PUSHINTEGER4(itran(1))
        itran(1) = itran(1) + idif
        CALL PUSHINTEGER4(itran(2))
        itran(2) = itran(2) - idif
!
!------ move top side BL variables downstream
        DO ibl=nbl(1),idif+2,-1
          tmp = ctau(ibl-idif, 1)
          ctau(ibl, 1) = tmp
          tmp0 = thet(ibl-idif, 1)
          CALL PUSHREAL8(thet(ibl, 1))
          thet(ibl, 1) = tmp0
          tmp1 = dstr(ibl-idif, 1)
          CALL PUSHREAL8(dstr(ibl, 1))
          dstr(ibl, 1) = tmp1
          tmp2 = uedg(ibl-idif, 1)
          CALL PUSHREAL8(uedg(ibl, 1))
          uedg(ibl, 1) = tmp2
        END DO
!
!------ set BL variables between old and new stagnation point
        dudx = uedg(idif+2, 1)/xssi(idif+2, 1)
        DO ibl=idif+1,2,-1
          tmp3 = ctau(idif+2, 1)
          ctau(ibl, 1) = tmp3
          tmp4 = thet(idif+2, 1)
          CALL PUSHREAL8(thet(ibl, 1))
          thet(ibl, 1) = tmp4
          tmp5 = dstr(idif+2, 1)
          CALL PUSHREAL8(dstr(ibl, 1))
          dstr(ibl, 1) = tmp5
          CALL PUSHREAL8(uedg(ibl, 1))
          uedg(ibl, 1) = dudx*xssi(ibl, 1)
        END DO
!
!------ move bottom side BL variables upstream
        DO ibl=2,nbl(2)
          tmp6 = ctau(ibl+idif, 2)
          ctau(ibl, 2) = tmp6
          tmp7 = thet(ibl+idif, 2)
          CALL PUSHREAL8(thet(ibl, 2))
          thet(ibl, 2) = tmp7
          tmp8 = dstr(ibl+idif, 2)
          CALL PUSHREAL8(dstr(ibl, 2))
          dstr(ibl, 2) = tmp8
          tmp9 = uedg(ibl+idif, 2)
          CALL PUSHREAL8(uedg(ibl, 2))
          uedg(ibl, 2) = tmp9
        END DO
        CALL PUSHCONTROL1B(0)
      ELSE
!
!------ increase in number of points on bottom side (IS=2)
        idif = istold - ist
!
        CALL PUSHINTEGER4(itran(1))
        itran(1) = itran(1) - idif
        CALL PUSHINTEGER4(itran(2))
        itran(2) = itran(2) + idif
!
!------ move bottom side BL variables downstream
        DO ibl=nbl(2),idif+2,-1
          tmp10 = ctau(ibl-idif, 2)
          ctau(ibl, 2) = tmp10
          tmp11 = thet(ibl-idif, 2)
          CALL PUSHREAL8(thet(ibl, 2))
          thet(ibl, 2) = tmp11
          tmp12 = dstr(ibl-idif, 2)
          CALL PUSHREAL8(dstr(ibl, 2))
          dstr(ibl, 2) = tmp12
          tmp13 = uedg(ibl-idif, 2)
          CALL PUSHREAL8(uedg(ibl, 2))
          uedg(ibl, 2) = tmp13
        END DO
!
!------ set BL variables between old and new stagnation point
        dudx = uedg(idif+2, 2)/xssi(idif+2, 2)
!        write(*,*) 'idif Ue xi dudx',
!     &    idif, UEDG(idif+2,2), xssi(idif+2,2), dudx
        DO ibl=idif+1,2,-1
          tmp14 = ctau(idif+2, 2)
          ctau(ibl, 2) = tmp14
          tmp15 = thet(idif+2, 2)
          CALL PUSHREAL8(thet(ibl, 2))
          thet(ibl, 2) = tmp15
          tmp16 = dstr(idif+2, 2)
          CALL PUSHREAL8(dstr(ibl, 2))
          dstr(ibl, 2) = tmp16
          CALL PUSHREAL8(uedg(ibl, 2))
          uedg(ibl, 2) = dudx*xssi(ibl, 2)
        END DO
!        write(*,*) 'Uenew xinew', idif+1, uedg(idif+1,2), xssi(idif+1,2)
!
!------ move top side BL variables upstream
        DO ibl=2,nbl(1)
          tmp17 = ctau(ibl+idif, 1)
          ctau(ibl, 1) = tmp17
          tmp18 = thet(ibl+idif, 1)
          CALL PUSHREAL8(thet(ibl, 1))
          thet(ibl, 1) = tmp18
          tmp19 = dstr(ibl+idif, 1)
          CALL PUSHREAL8(dstr(ibl, 1))
          dstr(ibl, 1) = tmp19
          tmp20 = uedg(ibl+idif, 1)
          CALL PUSHREAL8(uedg(ibl, 1))
          uedg(ibl, 1) = tmp20
        END DO
        CALL PUSHCONTROL1B(1)
      END IF
!
!----- tweak Ue so it's not zero, in case stag. point is right on node
      ueps = 1.0e-7
      DO is=1,2
        DO ibl=2,nbl(is)
          i = ipan(ibl, is)
          IF (uedg(ibl, is) .LE. ueps) THEN
            CALL PUSHREAL8(uedg(ibl, is))
            uedg(ibl, is) = ueps
            CALL PUSHREAL8(qvis(i))
            qvis(i) = vti(ibl, is)*ueps
            CALL PUSHREAL8(gam(i))
            gam(i) = vti(ibl, is)*ueps
            CALL PUSHCONTROL1B(1)
          ELSE
            CALL PUSHCONTROL1B(0)
          END IF
        END DO
        CALL PUSHINTEGER4(ibl - 1)
      END DO
      CALL PUSHCONTROL1B(0)
    END IF
!
!
!---- set new mass array since Ue has been tweaked
    DO is=1,2
      DO ibl=2,nbl(is)
        mass(ibl, is) = dstr(ibl, is)*uedg(ibl, is)
      END DO
      CALL PUSHINTEGER4(ibl - 1)
    END DO
    CALL PUSHREAL8(dudx)
    CALL PUSHINTEGER4(idif)
  END SUBROUTINE STMOVE_FWD

